extern const uint32_t kBrDictOffsets[32];
extern const uint8_t kBrDictSizeBits[32];
extern const uint8_t kBrUtf8Lut0[256];
extern const uint8_t kBrUtf8Lut1[256];
extern const uint8_t kBrSignedLut[256];

typedef struct {
  const char* prefix;
  int prefix_len;
  const char* suffix;
  int suffix_len;
  int type; /* 0 identity, 1..9 omit last N, 10 upper first, 11 upper all,
               12..20 omit first N-11 */
} BrTransform;

#define BR_NUM_TRANSFORMS 121
extern const BrTransform kBrTransforms[BR_NUM_TRANSFORMS];

/* Writes transformed word to dst (needs slack of a few bytes); returns length */
int BrTransformWord(uint8_t* dst, const uint8_t* word, int len, int idx);

static inline uint8_t BrContext(uint8_t p1, uint8_t p2, int mode) {
  switch (mode) {
    case BR_CONTEXT_LSB6: return (uint8_t)(p1 & 0x3F);
    case BR_CONTEXT_MSB6: return (uint8_t)(p1 >> 2);
    case BR_CONTEXT_UTF8: return (uint8_t)(kBrUtf8Lut0[p1] | kBrUtf8Lut1[p2]);
    default: return (uint8_t)((kBrSignedLut[p1] << 3) | kBrSignedLut[p2]);
  }
}

static inline uint32_t BrLog2Floor(uint64_t v) {
  uint32_t r = 0;
  while (v >>= 1) r++;
  return r;
}

