  87040, 93696, 100864, 104704, 106752, 108928, 113536, 115968, 118528,
  119872, 121280, 122016, 0, 0, 0, 0, 0, 0, 0
};

static const BrTransform kTransformTable[BR_NUM_TRANSFORMS] = {
#include "transforms.inc"
};
const BrTransform kBrTransforms[BR_NUM_TRANSFORMS] = {
#include "transforms.inc"
};

static int ToUpper(uint8_t* p) {
  if (p[0] < 0xC0) {
    if (p[0] >= 'a' && p[0] <= 'z') p[0] ^= 32;
    return 1;
  }
  if (p[0] < 0xE0) {
    p[1] ^= 32;
    return 2;
  }
  p[2] ^= 5;
  return 3;
}

int BrTransformWord(uint8_t* dst, const uint8_t* word, int len, int idx) {
  const BrTransform* t = &kTransformTable[idx];
  int n = 0;
  int i;
  int type = t->type;
  for (i = 0; i < t->prefix_len; ++i) dst[n++] = (uint8_t)t->prefix[i];
  if (type >= 1 && type <= 9) {
    len -= type;
  } else if (type >= 12 && type <= 20) {
    int skip = type - 11;
    word += skip;
    len -= skip;
  }
  for (i = 0; i < len; ++i) dst[n++] = word[i];
  if (type == 10 && len > 0) {
    ToUpper(&dst[n - len]);
  } else if (type == 11) {
    uint8_t* p = &dst[n - (len > 0 ? len : 0)];
    int rem = len;
    while (rem > 0) {
      int step = ToUpper(p);
      p += step;
      rem -= step;
    }
  }
  for (i = 0; i < t->suffix_len; ++i) dst[n++] = (uint8_t)t->suffix[i];
  return n;
}
