static const char* PrintablePath(const char* path) { return path ? path : "con"; }

static const char* FileName(const char* path) {
  const char* separator_position = strrchr(path, '/');
  if (separator_position) path = separator_position + 1;
  return path;
}

static void Crash(void) {
  fflush(NULL);
  signal(SIGSEGV, SIG_DFL);
  raise(SIGSEGV);
  abort();
}

static int ParseInt(const char* s, int low, int high, int* result) {
  int value = 0;
  int i;
  for (i = 0; i < 5; ++i) {
    char c = s[i];
    if (c == 0) break;
    if (s[i] < '0' || s[i] > '9') return 0;
    value = (10 * value) + (c - '0');
  }
  if (i == 0) return 0;
  if (i > 1 && s[0] == '0') return 0;
  if (s[i] != 0) return 0;
  if (value < low || value > high) return 0;
  *result = value;
  return 1;
}

static int Base64Value(char c) {
  if (c >= 'A' && c <= 'Z') return c - 'A';
  if (c >= 'a' && c <= 'z') return c - 'a' + 26;
  if (c >= '0' && c <= '9') return c - '0' + 52;
  if (c == '+' || c == '-') return 62;
  if (c == '/' || c == '_') return 63;
  return -1;
}

/* Returns 1 on success. */
static int ParseBase64(const char* str, uint8_t* out, size_t* out_len) {
  size_t n = 0;
  uint32_t acc = 0;
  int bits = 0;
  int pad = 0;
  for (; *str; ++str) {
    char c = *str;
    int v;
    if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
    if (c == '=') {
      pad++;
      if (pad > 2) return 0;
      continue;
    }
    if (pad) return 0;
    v = Base64Value(c);
    if (v < 0) return 0;
    acc = (acc << 6) | (uint32_t)v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      if (n >= MAX_COMMENT_LEN) return 0;
      out[n++] = (uint8_t)(acc >> bits);
      acc &= (1u << bits) - 1;
    }
  }
  *out_len = n;
  return 1;
}

static int StartsWithName(const char* name, const char* prefix) {
  size_t len = strlen(prefix);
  if (strncmp(name, prefix, len) != 0) return 0;
  return name[len] == 0 || name[len] == '.';
}

