        }
        command_set = 1;
        command = COMMAND_TEST_INTEGRITY;
      } else if (strcmp("verbose", arg) == 0) {
        if (params->verbosity > 0) {
          fprintf(stderr, "argument --verbose / -v already set\n");
          return COMMAND_INVALID;
        }
        params->verbosity = 1;
      } else if (strcmp("version", arg) == 0) {
        return COMMAND_VERSION;
      } else {
        const char* value = strchr(arg, '=');
        size_t key_len;
        if (!value || value[1] == 0) {
          fprintf(stderr, "must pass the parameter as --%s=value\n", arg);
          return COMMAND_INVALID;
        }
        key_len = (size_t)(value - arg);
        value++;
        if (strncmp("comment", arg, key_len) == 0) {
          if (comment_set) {
            fprintf(stderr, "comment already set\n");
            return COMMAND_INVALID;
          }
          if (!ParseBase64(value, params->comment, &params->comment_len)) {
            fprintf(stderr, "invalid base64-encoded comment\n");
            return COMMAND_INVALID;
          }
          comment_set = 1;
        } else if (strncmp("dictionary", arg, key_len) == 0) {
          if (params->dictionary_path) {
            fprintf(stderr, "dictionary path already set\n");
            return COMMAND_INVALID;
          }
          params->dictionary_path = value;
        } else if (strncmp("lgwin", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, 24, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < 10) {
            fprintf(stderr,
                    "lgwin parameter (%d) smaller than the minimum (%d)\n",
                    params->lgwin, 10);
            return COMMAND_INVALID;
          }
        } else if (strncmp("large_window", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, 30, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < 10) {
            fprintf(stderr,
                    "lgwin parameter (%d) smaller than the minimum (%d)\n",
                    params->lgwin, 10);
            return COMMAND_INVALID;
          }
        } else if (strncmp("output", arg, key_len) == 0) {
          if (output_set) {
            fprintf(stderr,
                    "write to standard output already set (--output)\n");
            return COMMAND_INVALID;
          }
          params->output_path = value;
        } else if (strncmp("quality", arg, key_len) == 0) {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = ParseInt(value, 0, 11, &params->quality);
          if (!quality_set) {
            fprintf(stderr, "error parsing quality value [%s]\n", value);
            return COMMAND_INVALID;
          }
        } else if (strncmp("suffix", arg, key_len) == 0) {
          if (suffix_set) {
            fprintf(stderr, "suffix already set\n");
            return COMMAND_INVALID;
          }
          suffix_set = 1;
          params->suffix = value;
        } else {
          fprintf(stderr, "invalid parameter: [%s]\n", arg);
          return COMMAND_INVALID;
        }
      }
    }
  }

  params->input_count = input_count;
  params->longest_path_len = longest_path_len;
  params->decompress = (command == COMMAND_DECOMPRESS);
  params->test_integrity = (command == COMMAND_TEST_INTEGRITY);

  if (input_count > 1 && output_set) return COMMAND_INVALID;
  if (params->test_integrity) {
    if (params->output_path) return COMMAND_INVALID;
    if (params->write_to_stdout) return COMMAND_INVALID;
  }
  if (params->reject_uncompressible && params->write_to_stdout) {
    return COMMAND_INVALID;
  }
  if (params->allow_concatenated && command != COMMAND_DECOMPRESS) {
    return COMMAND_INVALID;
  }
  if (params->allow_concatenated && params->comment_len) {
    return COMMAND_INVALID;
  }
  return command;
}

static void PrintVersion(void) { fprintf(stdout, "brotli 1.2.0\n"); }

static void PrintHelp(const char* name, int error) {
  FILE* media = error ? stderr : stdout;
  fprintf(media, "Usage: %s%s", name, kUsageBody);
}

static int64_t FileSize(const char* path) {
  FILE* f = fopen(path, "rb");
  int64_t retval;
  if (f == NULL) return -1;
  if (fseeko(f, 0L, SEEK_END) != 0) {
    fclose(f);
    return -1;
  }
  retval = (int64_t)ftello(f);
  if (fclose(f) != 0) return -1;
  return retval;
}

static int OpenInputFile(Context* context, const char* input_path, FILE** f) {
  *f = NULL;
  context->fin_is_null = 0;
  if (!input_path) {
    *f = fdopen(STDIN_FILENO, "rb");
    if (!*f) context->fin_is_null = 1;
    return 1;
  }
  *f = fopen(input_path, "rb");
  if (!*f) {
    fprintf(stderr, "failed to open input file [%s]: %s\n",
            PrintablePath(input_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int OpenOutputFile(Context* context, const char* output_path, FILE** f,
                          int force) {
  int fd;
  *f = NULL;
  context->fout_is_null = 0;
  if (!output_path) {
    *f = fdopen(STDOUT_FILENO, "wb");
    if (!*f) context->fout_is_null = 1;
    return 1;
  }
  fd = open(output_path, O_CREAT | (force ? 0 : O_EXCL) | O_WRONLY | O_TRUNC,
            S_IRUSR | S_IWUSR);
  if (fd < 0) {
    fprintf(stderr, "failed to open output file [%s]: %s\n",
            PrintablePath(output_path), strerror(errno));
    return 0;
  }
  *f = fdopen(fd, "wb");
  if (!*f) {
    fprintf(stderr, "failed to open output file [%s]: %s\n",
            PrintablePath(output_path), strerror(errno));
    return 0;
  }
  return 1;
}

static void CopyStat(const char* input_path, const char* output_path) {
  struct stat statbuf;
  struct timespec times[2];
  int res;
  if (input_path == 0 || output_path == 0) return;
  if (stat(input_path, &statbuf) != 0) return;
  times[0] = statbuf.st_atim;
  times[1] = statbuf.st_mtim;
  utimensat(AT_FDCWD, output_path, times, 0);
  res = chmod(output_path, statbuf.st_mode & (S_IRWXU | S_IRWXG | S_IRWXO));
  if (res != 0) {
    fprintf(stderr, "setting access bits failed for [%s]: %s\n",
            PrintablePath(output_path), strerror(errno));
  }
  res = chown(output_path, (uid_t)-1, statbuf.st_gid);
  if (res != 0) {
    fprintf(stderr, "setting group failed for [%s]: %s\n",
            PrintablePath(output_path), strerror(errno));
  }
  res = chown(output_path, statbuf.st_uid, (gid_t)-1);
  if (res != 0) {
    fprintf(stderr, "setting user failed for [%s]: %s\n",
            PrintablePath(output_path), strerror(errno));
  }
}

static int NextFile(Context* context) {
  const char* arg;
  size_t arg_len;

  context->iterator++;
  context->input_file_length = -1;

  if (context->input_count == 0) {
    if (context->iterator > 1) return 0;
    context->current_input_path = NULL;
    context->current_output_path = context->output_path;
    return 1;
  }

  while (context->iterator == context->not_input_indices[context->ignore]) {
    context->iterator++;
    context->ignore++;
  }

  if (context->iterator >= context->argc) return 0;

  arg = context->argv[context->iterator];
  arg_len = strlen(arg);
  if (arg_len == 1 && arg[0] == '-') {
    context->current_input_path = NULL;
    context->current_output_path = context->output_path;
    return 1;
  }

  context->current_input_path = arg;
  context->input_file_length = FileSize(arg);
  context->current_output_path = context->output_path;

  if (context->output_path) return 1;
  if (context->write_to_stdout) return 1;

  strcpy(context->modified_path, arg);
  context->current_output_path = context->modified_path;
  if (context->decompress) {
    size_t suffix_len = strlen(context->suffix);
    char* name = (char*)FileName(context->modified_path);
    char* name_suffix;
    size_t name_len = strlen(name);
    if (name_len < suffix_len + 1) {
      fprintf(stderr, "empty output file name for [%s] input file\n",
              PrintablePath(arg));
      context->iterator_error = 1;
      return 0;
    }
    name_suffix = name + name_len - suffix_len;
    if (strcmp(context->suffix, name_suffix) != 0) {
      fprintf(stderr, "input file [%s] suffix mismatch\n", PrintablePath(arg));
      context->iterator_error = 1;
      return 0;
    }
    name_suffix[0] = 0;
    return 1;
  } else {
    strcpy(context->modified_path + arg_len, context->suffix);
    return 1;
  }
}

static int OpenFiles(Context* context) {
  int is_ok = OpenInputFile(context, context->current_input_path, &context->fin);
  if (!context->test_integrity && is_ok) {
    is_ok = OpenOutputFile(context, context->current_output_path,
                           &context->fout, context->force_overwrite);
  }
  return is_ok;
}

static int CloseFiles(Context* context, int rm_input, int rm_output) {
  int is_ok = 1;
  if (!context->test_integrity && context->fout) {
    if (fclose(context->fout) != 0) {
      if (is_ok) {
        fprintf(stderr, "fclose failed [%s]: %s\n",
                PrintablePath(context->current_output_path), strerror(errno));
      }
      is_ok = 0;
    }
    if (rm_output && context->current_output_path) {
      unlink(context->current_output_path);
    }
    if (!rm_output && is_ok && context->copy_stat) {
      CopyStat(context->current_input_path, context->current_output_path);
    }
  }
  if (context->fin) {
    if (fclose(context->fin) != 0) {
      if (is_ok) {
        fprintf(stderr, "fclose failed [%s]: %s\n",
                PrintablePath(context->current_input_path), strerror(errno));
      }
      is_ok = 0;
    }
  }
  if (rm_input && context->current_input_path) {
    unlink(context->current_input_path);
  }
  context->fin = NULL;
  context->fout = NULL;
  return is_ok;
}

static void InitializeBuffers(Context* context) {
  context->available_in = 0;
  context->next_in = NULL;
  context->available_out = FILE_BUFFER_SIZE;
  context->next_out = context->output;
  context->total_in = 0;
  context->total_out = 0;
  context->start_time = clock();
}

static int HasMoreInput(Context* context) {
  if (context->fin_is_null) Crash();
  return feof(context->fin) ? 0 : 1;
}

static int ProvideInput(Context* context) {
  if (context->fin_is_null) Crash();
  context->available_in =
      fread(context->input, 1, FILE_BUFFER_SIZE, context->fin);
  context->total_in += context->available_in;
  context->next_in = context->input;
  if (ferror(context->fin)) {
    fprintf(stderr, "failed to read input [%s]: %s\n",
            PrintablePath(context->current_input_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int WriteOutput(Context* context) {
  size_t out_size = (size_t)(context->next_out - context->output);
  context->total_out += out_size;
  if (out_size == 0) return 1;
  if (context->test_integrity) return 1;
  if (context->fout_is_null) Crash();
  fwrite(context->output, 1, out_size, context->fout);
  if (ferror(context->fout)) {
    fprintf(stderr, "failed to write output [%s]: %s\n",
            PrintablePath(context->current_output_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int ProvideOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = FILE_BUFFER_SIZE;
  context->next_out = context->output;
  return 1;
}

static int FlushOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = 0;
  context->next_out = context->output;
  return 1;
}

static void PrintBytes(size_t value) {
  if (value < 1024) {
    fprintf(stderr, "%d B", (int)value);
  } else if (value < 1048576) {
    fprintf(stderr, "%0.3f KiB", (double)value / 1024.0);
  } else if (value < 1073741824) {
    fprintf(stderr, "%0.3f MiB", (double)value / 1048576.0);
  } else {
    fprintf(stderr, "%0.3f GiB", (double)value / 1073741824.0);
  }
}

static void PrintFileProcessingProgress(Context* context) {
  fprintf(stderr, "[%s]: ", PrintablePath(context->current_input_path));
  PrintBytes(context->total_in);
  fprintf(stderr, " -> ");
  PrintBytes(context->total_out);
  fprintf(stderr, " in %1.2f sec",
          (double)(context->end_time - context->start_time) / CLOCKS_PER_SEC);
}

/* ---------------- decompression ---------------- */

static int OnMetadata(void* opaque, const uint8_t* data, size_t size) {
  Context* context = (Context*)opaque;
  size_t i;
  if (context->comment_state == COMMENT_INIT) {
    if (context->comment_len != size) {
      context->comment_state = COMMENT_BAD;
      return 1;
    }
    context->comment_pos = 0;
    context->comment_state = COMMENT_READ;
  }
  if (context->comment_state == COMMENT_READ) {
    for (i = 0; i < size; ++i) {
      if (context->comment_pos >= context->comment_len ||
          context->comment[context->comment_pos++] != data[i]) {
        context->comment_state = COMMENT_BAD;
        return 1;
      }
    }
    if (context->comment_pos == context->comment_len) {
      context->comment_state = COMMENT_OK;
    }
  }
  return 0;
}

/* Emits n bytes of decoded data through the CLI output buffer. */
static int EmitDecoded(Context* context, const uint8_t* data, size_t n) {
  while (n > 0) {
    size_t chunk;
    if (context->available_out == 0) {
      if (!ProvideOutput(context)) return 0;
    }
    chunk = n < context->available_out ? n : context->available_out;
    memcpy(context->next_out, data, chunk);
    context->next_out += chunk;
    context->available_out -= chunk;
    data += chunk;
    n -= chunk;
  }
  return 1;
}

static int DecompressFile(Context* context) {
  BrBuf in = {NULL, 0, 0};
  BrBuf out = {NULL, 0, 0};
  size_t pos = 0;
  int ok = 1;
  BrDecodeOptions opt;
  InitializeBuffers(context);
  memset(&opt, 0, sizeof(opt));
  opt.allow_large_window = 1;
  opt.dict = context->dictionary;
  opt.dict_len = context->dictionary_size;
  if (context->comment_len) {
    opt.on_metadata = OnMetadata;
    opt.opaque = context;
  }
  context->comment_state = context->comment_len ? COMMENT_INIT : COMMENT_OK;
  /* Read whole input. */
  for (;;) {
    if (!HasMoreInput(context)) break;
    if (!ProvideInput(context)) {
      free(in.data);
      return 0;
    }
    if (context->available_in) {
      if (!BrBufReserve(&in, context->available_in)) {
        fprintf(stderr, "out of memory\n");
        free(in.data);
        return 0;
      }
      memcpy(in.data + in.len, context->input, context->available_in);
      in.len += context->available_in;
    }
    context->available_in = 0;
  }
  for (;;) {
    size_t consumed = 0, flushed = 0;
    int rc;
    out.len = 0;
    rc = BrDecodeStream(in.data + pos, in.len - pos, &consumed, &out, &flushed,
                        &opt);
    if (rc == BRD_SUCCESS) {
      if (!EmitDecoded(context, out.data, out.len)) {
        ok = 0;
        break;
      }
      if (!FlushOutput(context)) {
        ok = 0;
        break;
      }
      pos += consumed;
      if (pos < in.len) {
        if (!context->allow_concatenated) {
          fprintf(stderr, "corrupt input [%s]\n",
                  PrintablePath(context->current_input_path));
          if (context->verbosity > 0) {
            fprintf(stderr, "reason: extra input\n");
          }
          ok = 0;
          break;
        }
        continue;
      }
      if (context->verbosity > 0) {
        context->end_time = clock();
        fprintf(stderr, "Decompressed ");
        PrintFileProcessingProgress(context);
        fprintf(stderr, "\n");
      }
      if (context->comment_state != COMMENT_OK) {
        fprintf(stderr, "corrupt input [%s]\n",
                PrintablePath(context->current_input_path));
        if (context->verbosity > 0) {
          fprintf(stderr, "reason: comment mismatch\n");
        }
      }
      ok = 1;
      break;
    } else {
      /* Emit what the reference streaming decoder would have released. */
      size_t written = 0;
      if (flushed > 0) {
        written = ((flushed - 1) / FILE_BUFFER_SIZE) * FILE_BUFFER_SIZE;
      }
      if (written > out.len) written = out.len;
      if (written) {
        context->available_out = FILE_BUFFER_SIZE;
        context->next_out = context->output;
        {
          size_t k;
          for (k = 0; k < written; k += FILE_BUFFER_SIZE) {
            memcpy(context->output, out.data + k, FILE_BUFFER_SIZE);
            context->next_out = context->output + FILE_BUFFER_SIZE;
            if (!WriteOutput(context)) break;
          }
        }
      }
      if (rc == BRD_ERR_METADATA_ABORT || context->comment_state == COMMENT_BAD) {
        fprintf(stderr, "corrupt input [%s]\n",
                PrintablePath(context->current_input_path));
        if (context->verbosity > 0) {
          fprintf(stderr, "reason: comment mismatch\n");
        }
      } else if (rc == BRD_NEEDS_MORE_INPUT) {
        fprintf(stderr, "corrupt input [%s]\n",
                PrintablePath(context->current_input_path));
        if (context->verbosity > 0) {
          fprintf(stderr, "reason: truncated input\n");
        }
      } else {
        fprintf(stderr, "corrupt input [%s]\n",
                PrintablePath(context->current_input_path));
        if (context->verbosity > 0) {
          fprintf(stderr, "reason: %s (%d)\n", BrDecodeErrorString(rc), rc);
        }
      }
      ok = 0;
      break;
    }
  }
  free(in.data);
  free(out.data);
  return ok;
}

static int DecompressFiles(Context* context) {
  while (NextFile(context)) {
    int is_ok = 1;
    int rm_input = 0;
    int rm_output = 1;
    is_ok = OpenFiles(context);
    if (is_ok && !context->current_input_path && !context->force_overwrite &&
        isatty(STDIN_FILENO)) {
      fprintf(stderr, "Use -h help. Use -f to force input from a terminal.\n");
      is_ok = 0;
    }
    if (is_ok) is_ok = DecompressFile(context);
    if (is_ok) {
      rm_output = 0;
      rm_input = context->junk_source;
      if (context->reject_uncompressible &&
          context->total_out > context->total_in) {
        rm_output = 1;
        rm_input = 0;
        if (context->verbosity > 0) {
          fprintf(stderr, "Output is larger than input\n");
        }
      }
    }
    if (!CloseFiles(context, rm_input, rm_output)) is_ok = 0;
    if (!is_ok) return 0;
  }
  return 1;
}

/* ---------------- compression ---------------- */

static int CompressFile(Context* context, BrEncoder* s) {
  int is_eof = 0;
  int prologue = context->comment_len != 0;
  InitializeBuffers(context);
  for (;;) {
    if (context->available_in == 0 && !is_eof) {
      if (!ProvideInput(context)) return 0;
      is_eof = !HasMoreInput(context);
    }

    if (prologue) {
      size_t avail = context->comment_len;
      const uint8_t* next = context->comment;
      if (!BrEncCompressStream(s, BRE_OP_EMIT_METADATA, &avail, &next,
                               &context->available_out, &context->next_out)) {
        fprintf(stderr, "failed to compress data [%s]\n",
                PrintablePath(context->current_input_path));
        return 0;
      }
      if (avail == 0 && !BrEncHasMoreOutput(s)) prologue = 0;
      if (context->available_out == 0) {
        if (!ProvideOutput(context)) return 0;
      }
      continue;
    }

    if (!BrEncCompressStream(s, is_eof ? BRE_OP_FINISH : BRE_OP_PROCESS,
                             &context->available_in, &context->next_in,
                             &context->available_out, &context->next_out)) {
      fprintf(stderr, "failed to compress data [%s]\n",
              PrintablePath(context->current_input_path));
      return 0;
    }

    if (context->available_out == 0) {
      if (!ProvideOutput(context)) return 0;
    }

    if (BrEncIsFinished(s)) {
      if (!FlushOutput(context)) return 0;
      if (context->verbosity > 0) {
        context->end_time = clock();
        fprintf(stderr, "Compressed ");
        PrintFileProcessingProgress(context);
        fprintf(stderr, "\n");
      }
      return 1;
    }
  }
}

static int CompressFiles(Context* context) {
  while (NextFile(context)) {
    int is_ok = 1;
    int rm_input = 0;
    int rm_output = 1;
    BrEncoder* s = BrEncCreate();
    if (!s) {
      fprintf(stderr, "out of memory\n");
      return 0;
    }
    BrEncSetParam(s, BRE_PARAM_QUALITY, (uint32_t)context->quality);
    if (context->lgwin > 0) {
      if (context->lgwin > 24) {
        BrEncSetParam(s, BRE_PARAM_LARGE_WINDOW, 1u);
      }
      BrEncSetParam(s, BRE_PARAM_LGWIN, (uint32_t)context->lgwin);
    } else {
      uint32_t lgwin = DEFAULT_LGWIN;
      if (context->input_file_length >= 0) {
        lgwin = 10;
        while (((uint64_t)1 << lgwin) - 16 <
               (uint64_t)context->input_file_length) {
          lgwin++;
          if (lgwin == 24) break;
        }
      }
      BrEncSetParam(s, BRE_PARAM_LGWIN, lgwin);
    }
    if (context->input_file_length > 0) {
      uint32_t size_hint = context->input_file_length < (1 << 30)
                               ? (uint32_t)context->input_file_length
                               : (1u << 30);
      BrEncSetParam(s, BRE_PARAM_SIZE_HINT, size_hint);
    }
    if (context->dictionary) {
      BrEncAttachRawDictionary(s, context->dictionary,
                               context->dictionary_size);
    }
    is_ok = OpenFiles(context);
    if (is_ok && !context->current_output_path && !context->force_overwrite &&
        isatty(STDOUT_FILENO)) {
      fprintf(stderr, "Use -h help. Use -f to force output to a terminal.\n");
      is_ok = 0;
    }
    if (is_ok) is_ok = CompressFile(context, s);
    BrEncDestroy(s);
    if (is_ok) {
      rm_output = 0;
      rm_input = context->junk_source;
      if (context->reject_uncompressible &&
          context->total_out >= context->total_in) {
        rm_output = 1;
        rm_input = 0;
        if (context->verbosity > 0) {
          fprintf(stderr, "Output is larger than input\n");
        }
      }
    }
    if (!CloseFiles(context, rm_input, rm_output)) is_ok = 0;
    if (!is_ok) return 0;
  }
  return 1;
}

static int ReadDictionary(Context* context) {
  static const int64_t kMaxDictionarySize = 0x3FFFFFC - ((1 << 24) - 16);
  FILE* f;
  int64_t file_size_64;
  uint8_t* buffer;
  size_t bytes_read;

  if (context->dictionary_path == NULL) return 1;
  f = fopen(context->dictionary_path, "rb");
  if (f == NULL) {
    fprintf(stderr, "failed to open dictionary file [%s]: %s\n",
            PrintablePath(context->dictionary_path), strerror(errno));
    return 0;
  }
  file_size_64 = FileSize(context->dictionary_path);
  if (file_size_64 == -1) {
    fprintf(stderr, "could not get size of dictionary file [%s]",
            PrintablePath(context->dictionary_path));
    fclose(f);
    return 0;
  }
  if (file_size_64 > kMaxDictionarySize) {
    fprintf(stderr, "dictionary [%s] is larger than maximum allowed: %d\n",
            PrintablePath(context->dictionary_path), (int)kMaxDictionarySize);
    fclose(f);
    return 0;
  }
  context->dictionary_size = (size_t)file_size_64;
  buffer = (uint8_t*)malloc(context->dictionary_size ? context->dictionary_size : 1);
  if (!buffer) {
    fprintf(stderr, "could not read dictionary: out of memory\n");
    fclose(f);
    return 0;
  }
  bytes_read = fread(buffer, sizeof(uint8_t), context->dictionary_size, f);
  if (bytes_read != context->dictionary_size) {
    free(buffer);
    fprintf(stderr, "failed to read dictionary [%s]: %s\n",
            PrintablePath(context->dictionary_path), strerror(errno));
    fclose(f);
    return 0;
  }
  fclose(f);
  context->dictionary = buffer;
  return 1;
}

int main(int argc, char** argv) {
  Command command;
  static Context context;
  int is_ok = 1;

  memset(&context, 0, sizeof(context));
  context.quality = 11;
  context.lgwin = -1;
  context.copy_stat = 1;
  context.suffix = DEFAULT_SUFFIX;
  context.longest_path_len = 1;
  context.argc = argc;
  context.argv = argv;

  command = ParseParams(&context);

  if (command == COMMAND_COMPRESS || command == COMMAND_DECOMPRESS ||
      command == COMMAND_TEST_INTEGRITY) {
    if (!ReadDictionary(&context)) {
      is_ok = 0;
    } else {
      size_t modified_path_len =
          context.longest_path_len + strlen(context.suffix) + 1;
      context.modified_path = (char*)malloc(modified_path_len);
      context.buffer = (uint8_t*)malloc(FILE_BUFFER_SIZE * 2);
      if (!context.modified_path || !context.buffer) {
        fprintf(stderr, "out of memory\n");
        is_ok = 0;
      } else {
        context.input = context.buffer;
        context.output = context.buffer + FILE_BUFFER_SIZE;
        switch (command) {
          case COMMAND_COMPRESS:
            is_ok = CompressFiles(&context);
            break;
          case COMMAND_DECOMPRESS:
          case COMMAND_TEST_INTEGRITY:
            is_ok = DecompressFiles(&context);
            break;
          default:
            break;
        }
      }
    }
  } else if (command == COMMAND_VERSION) {
    PrintVersion();
  } else if (command == COMMAND_HELP) {
    PrintHelp(FileName(argv[0]), 1);
  } else {
    PrintHelp(FileName(argv[0]), 0);
    is_ok = 0;
  }

  if (context.iterator_error) is_ok = 0;

  free(context.dictionary);
  free(context.modified_path);
  free(context.buffer);

  if (!is_ok) exit(1);
  return 0;
}
