/* Shared helpers for the encoder. */
#ifndef BR_ENC_COMMON_H_
#define BR_ENC_COMMON_H_

#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "brcommon.h"

#define BR_MIN(a, b) ((a) < (b) ? (a) : (b))
#define BR_MAX(a, b) ((a) > (b) ? (a) : (b))

static inline uint32_t Load32(const uint8_t* p) {
  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) |
         ((uint32_t)p[3] << 24);
}
static inline uint64_t Load64(const uint8_t* p) {
  uint64_t v;
  memcpy(&v, p, 8);
  return v; /* little endian host assumed */
}

static inline uint32_t Log2FloorNonZero(size_t n) {
  uint32_t r = 0;
  while (n >>= 1) r++;
  return r;
}

/* Bit writer: same semantics as the reference (OR into first byte, zero the
   following 7 bytes). Storage must have 8 bytes of slack. */
static inline void WriteBits(size_t n_bits, uint64_t bits, size_t* pos,
                             uint8_t* array) {
  uint8_t* p = &array[*pos >> 3];
  uint64_t v = (uint64_t)(*p);
  v |= bits << (*pos & 7);
  memcpy(p, &v, 8);
  *pos += n_bits;
}

static inline void WriteBitsPrepareStorage(size_t pos, uint8_t* array) {
  array[pos >> 3] = 0;
}

static inline size_t FindMatchLengthWithLimit(const uint8_t* s1,
                                              const uint8_t* s2,
                                              size_t limit) {
  size_t matched = 0;
  while (matched + 8 <= limit) {
    uint64_t x = Load64(s2 + matched) ^ Load64(s1 + matched);
    if (x) {
      return matched + ((size_t)__builtin_ctzll(x) >> 3);
    }
    matched += 8;
  }
  while (matched < limit && s1[matched] == s2[matched]) ++matched;
  return matched;
}

extern double kBrLog2Table[256];
void BrInitLog2Table(void);

static inline double FastLog2(size_t v) {
  if (v < 256) return kBrLog2Table[v];
  return log2((double)v);
}

#endif
