void BrSortHuffmanTreeItems(HuffmanTree* items, size_t n) {
  /* The order is total, so any correct sort yields the same result. */
  size_t i;
  if (n < 2) return;
  if (n < 13) {
    for (i = 1; i < n; ++i) {
      HuffmanTree tmp = items[i];
      size_t k = i;
      while (k > 0 && TreeLess(&tmp, &items[k - 1])) {
        items[k] = items[k - 1];
        k--;
      }
      items[k] = tmp;
    }
  } else {
    static const size_t gaps[] = {132, 57, 23, 10, 4, 1};
    int g = n < 57 ? 2 : 0;
    for (; g < 6; ++g) {
      size_t gap = gaps[g];
      for (i = gap; i < n; ++i) {
        size_t j = i;
        HuffmanTree tmp = items[i];
        for (; j >= gap && TreeLess(&tmp, &items[j - gap]); j -= gap) {
          items[j] = items[j - gap];
