    if (n == 1) {
      depth[tree[0].index_right_or_value_] = 1;
      break;
    }
    BrSortHuffmanTreeItems(tree, n);
    tree[n] = sentinel;
    tree[n + 1] = sentinel;
    i = 0;
    j = n + 1;
    for (k = n - 1; k != 0; --k) {
      size_t left, right;
      if (tree[i].total_count_ <= tree[j].total_count_) {
        left = i;
        ++i;
      } else {
        left = j;
        ++j;
