static void ReorderBitsFromDepths(BrOnePassArena* s);

void BrInitCommandPrefixCodes(BrOnePassArena* s) {
  memcpy(s->cmd_depth, kDefaultCommandDepths, sizeof(kDefaultCommandDepths));
  ReorderBitsFromDepths(s);
  memcpy(s->cmd_code, kDefaultCommandCode, sizeof(kDefaultCommandCode));
  s->cmd_code_numbits = kDefaultCommandCodeNumBits;
}

/* Computes cmd_bits from cmd_depth following the full-alphabet order. */
static void ReorderBitsFromDepths(BrOnePassArena* s) {
  uint8_t* depth = s->cmd_depth;
  uint16_t* bits = s->cmd_bits;
  uint8_t* tmp_depth = s->tmp_depth;
  uint16_t* tmp_bits = s->tmp_bits;
  memset(tmp_depth, 0, 64);
  memcpy(tmp_depth, depth, 24);
  memcpy(tmp_depth + 24, depth + 40, 8);
  memcpy(tmp_depth + 32, depth + 24, 8);
  memcpy(tmp_depth + 40, depth + 48, 8);
  memcpy(tmp_depth + 48, depth + 32, 8);
  memcpy(tmp_depth + 56, depth + 56, 8);
  BrConvertBitDepthsToSymbols(tmp_depth, 64, tmp_bits);
  memcpy(bits, tmp_bits, 24 * 2);
  memcpy(bits + 24, tmp_bits + 32, 8 * 2);
  memcpy(bits + 32, tmp_bits + 48, 8 * 2);
  memcpy(bits + 40, tmp_bits + 24, 8 * 2);
  memcpy(bits + 48, tmp_bits + 40, 8 * 2);
  memcpy(bits + 56, tmp_bits + 56, 8 * 2);
  BrConvertBitDepthsToSymbols(&depth[64], 64, &bits[64]);
}

static inline uint32_t Hash(const uint8_t* p, size_t shift) {
  const uint64_t h = (Load64(p) << 24) * kHashMul32;
  return (uint32_t)(h >> shift);
}

static inline uint32_t HashBytesAtOffset(uint64_t v, int offset, size_t shift) {
  const uint64_t h = ((v >> (8 * offset)) << 24) * kHashMul32;
  return (uint32_t)(h >> shift);
}

static inline int IsMatch(const uint8_t* p1, const uint8_t* p2) {
  return Load32(p1) == Load32(p2) && p1[4] == p2[4];
}

static size_t BuildAndStoreLiteralPrefixCode(BrOnePassArena* s,
                                             const uint8_t* input,
                                             const size_t input_size,
                                             uint8_t depths[256],
                                             uint16_t bits[256],
                                             size_t* storage_ix,
                                             uint8_t* storage) {
  uint32_t* histogram = s->histogram;
  size_t histogram_total;
  size_t i;
  memset(histogram, 0, sizeof(s->histogram));
  if (input_size < (1 << 15)) {
    for (i = 0; i < input_size; ++i) ++histogram[input[i]];
    histogram_total = input_size;
    for (i = 0; i < 256; ++i) {
      const uint32_t adjust = 2 * BR_MIN(histogram[i], 11u);
      histogram[i] += adjust;
      histogram_total += adjust;
    }
  } else {
    static const size_t kSampleRate = 29;
    for (i = 0; i < input_size; i += kSampleRate) ++histogram[input[i]];
    histogram_total = (input_size + kSampleRate - 1) / kSampleRate;
    for (i = 0; i < 256; ++i) {
      const uint32_t adjust = 1 + 2 * BR_MIN(histogram[i], 11u);
      histogram[i] += adjust;
      histogram_total += adjust;
    }
  }
  BrBuildAndStoreHuffmanTreeFast(s->tree, histogram, histogram_total, 8,
                                 depths, bits, storage_ix, storage);
  {
    size_t literal_ratio = 0;
    for (i = 0; i < 256; ++i) {
      if (histogram[i]) literal_ratio += histogram[i] * depths[i];
    }
    return (literal_ratio * 125) / histogram_total;
  }
}

static void BuildAndStoreCommandPrefixCode(BrOnePassArena* s,
                                           size_t* storage_ix,
                                           uint8_t* storage) {
  const uint32_t* const histogram = s->cmd_histo;
  uint8_t* const depth = s->cmd_depth;
  uint8_t* tmp_depth = s->tmp_depth;
  memset(tmp_depth, 0, 704);
  BrCreateHuffmanTree(histogram, 64, 15, s->tree, depth);
  BrCreateHuffmanTree(&histogram[64], 64, 14, s->tree, &depth[64]);
  ReorderBitsFromDepths(s);
  {
    size_t i;
    memset(tmp_depth, 0, 64);
    memcpy(tmp_depth, depth, 8);
    memcpy(tmp_depth + 64, depth + 8, 8);
    memcpy(tmp_depth + 128, depth + 16, 8);
    memcpy(tmp_depth + 192, depth + 24, 8);
    memcpy(tmp_depth + 384, depth + 32, 8);
    for (i = 0; i < 8; ++i) {
      tmp_depth[128 + 8 * i] = depth[40 + i];
      tmp_depth[256 + 8 * i] = depth[48 + i];
      tmp_depth[448 + 8 * i] = depth[56 + i];
    }
    BrStoreHuffmanTree(tmp_depth, 704, s->tree, storage_ix, storage);
  }
  BrStoreHuffmanTree(&depth[64], 64, s->tree, storage_ix, storage);
}

static inline void EmitInsertLen(size_t insertlen, const uint8_t depth[128],
                                 const uint16_t bits[128], uint32_t histo[128],
                                 size_t* storage_ix, uint8_t* storage) {
