static inline void EmitDistance(size_t distance, const uint8_t depth[128],
                                const uint16_t bits[128], uint32_t histo[128],
                                size_t* storage_ix, uint8_t* storage) {
  const size_t d = distance + 3;
  const uint32_t nbits = Log2FloorNonZero(d) - 1u;
  const size_t prefix = (d >> nbits) & 1;
  const size_t offset = (2 + prefix) << nbits;
  const size_t distcode = 2 * (nbits - 1) + prefix + 80;
  WriteBits(depth[distcode], bits[distcode], storage_ix, storage);
  WriteBits(nbits, d - offset, storage_ix, storage);
  ++histo[distcode];
}

static inline void EmitLiterals(const uint8_t* input, const size_t len,
                                const uint8_t depth[256],
                                const uint16_t bits[256], size_t* storage_ix,
                                uint8_t* storage) {
  size_t j;
  for (j = 0; j < len; j++) {
    const uint8_t lit = input[j];
    WriteBits(depth[lit], bits[lit], storage_ix, storage);
  }
}

static void StoreMetaBlockHeader(size_t len, int is_uncompressed,
                                 size_t* storage_ix, uint8_t* storage) {
  size_t nibbles = 6;
  WriteBits(1, 0, storage_ix, storage);
  if (len <= (1U << 16)) {
    nibbles = 4;
  } else if (len <= (1U << 20)) {
    nibbles = 5;
  }
  WriteBits(2, nibbles - 4, storage_ix, storage);
  WriteBits(nibbles * 4, len - 1, storage_ix, storage);
  WriteBits(1, (uint64_t)is_uncompressed, storage_ix, storage);
}

static void UpdateBits(size_t n_bits, uint32_t bits, size_t pos,
                       uint8_t* array) {
  while (n_bits > 0) {
    size_t byte_pos = pos >> 3;
    size_t n_unchanged_bits = pos & 7;
    size_t n_changed_bits = BR_MIN(n_bits, 8 - n_unchanged_bits);
    size_t total_bits = n_unchanged_bits + n_changed_bits;
    uint32_t mask =
        (~((1u << total_bits) - 1u)) | ((1u << n_unchanged_bits) - 1u);
    uint32_t unchanged_bits = array[byte_pos] & mask;
    uint32_t changed_bits = bits & ((1u << n_changed_bits) - 1u);
    array[byte_pos] =
        (uint8_t)((changed_bits << n_unchanged_bits) | unchanged_bits);
    n_bits -= n_changed_bits;
    bits >>= n_changed_bits;
    pos += n_changed_bits;
  }
}

static void RewindBitPosition(const size_t new_storage_ix, size_t* storage_ix,
                              uint8_t* storage) {
  const size_t bitpos = new_storage_ix & 7;
  const size_t mask = (1u << bitpos) - 1;
  storage[new_storage_ix >> 3] &= (uint8_t)mask;
  *storage_ix = new_storage_ix;
}

static int ShouldMergeBlock(BrOnePassArena* s, const uint8_t* data,
                            size_t len, const uint8_t* depths) {
  uint32_t* histo = s->histogram;
  static const size_t kSampleRate = 43;
  size_t i;
  memset(histo, 0, sizeof(s->histogram));
  for (i = 0; i < len; i += kSampleRate) ++histo[data[i]];
  {
    const size_t total = (len + kSampleRate - 1) / kSampleRate;
    double r = (FastLog2(total) + 0.5) * (double)total + 200;
    for (i = 0; i < 256; ++i) {
      r -= (double)histo[i] * (depths[i] + FastLog2(histo[i]));
    }
    return r >= 0.0;
  }
}

static inline int ShouldUseUncompressedMode(const uint8_t* metablock_start,
                                            const uint8_t* next_emit,
                                            const size_t insertlen,
                                            const size_t literal_ratio) {
  const size_t compressed = (size_t)(next_emit - metablock_start);
  if (compressed * 50 > insertlen) {
    return 0;
  } else {
    return literal_ratio > 980;
  }
}

static void EmitUncompressedMetaBlock(const uint8_t* begin, const uint8_t* end,
                                      const size_t storage_ix_start,
                                      size_t* storage_ix, uint8_t* storage) {
  const size_t len = (size_t)(end - begin);
  RewindBitPosition(storage_ix_start, storage_ix, storage);
  StoreMetaBlockHeader(len, 1, storage_ix, storage);
  *storage_ix = (*storage_ix + 7u) & ~7u;
  memcpy(&storage[*storage_ix >> 3], begin, len);
  *storage_ix += len << 3;
  storage[*storage_ix >> 3] = 0;
}

static void CompressFragmentFastImpl(BrOnePassArena* s, const uint8_t* input,
                                     size_t input_size, int is_last,
                                     int* table, size_t table_bits,
                                     size_t* storage_ix, uint8_t* storage) {
  uint8_t* cmd_depth = s->cmd_depth;
  uint16_t* cmd_bits = s->cmd_bits;
  uint32_t* cmd_histo = s->cmd_histo;
  uint8_t* lit_depth = s->lit_depth;
  uint16_t* lit_bits = s->lit_bits;
  const uint8_t* ip_end;
  const uint8_t* next_emit = input;
  const uint8_t* base_ip = input;
  static const size_t kFirstBlockSize = 3 << 15;
  static const size_t kMergeBlockSize = 1 << 16;
  const size_t kInputMarginBytes = 16;
  const size_t kMinMatchLen = 5;
  const uint8_t* metablock_start = input;
  size_t block_size = BR_MIN(input_size, kFirstBlockSize);
  size_t total_block_size = block_size;
  size_t mlen_storage_ix = *storage_ix + 3;
  size_t literal_ratio;
  const uint8_t* ip;
  int last_distance;
  const size_t shift = 64u - table_bits;

  StoreMetaBlockHeader(block_size, 0, storage_ix, storage);
  WriteBits(13, 0, storage_ix, storage);
  literal_ratio = BuildAndStoreLiteralPrefixCode(s, input, block_size,
                                                 s->lit_depth, s->lit_bits,
                                                 storage_ix, storage);
  {
    size_t i;
    for (i = 0; i + 7 < s->cmd_code_numbits; i += 8) {
      WriteBits(8, s->cmd_code[i >> 3], storage_ix, storage);
    }
  }
  WriteBits(s->cmd_code_numbits & 7, s->cmd_code[s->cmd_code_numbits >> 3],
            storage_ix, storage);

emit_commands:
  memcpy(s->cmd_histo, kCmdHistoSeed, sizeof(kCmdHistoSeed));
  ip = input;
  last_distance = -1;
  ip_end = input + block_size;

  if (block_size >= kInputMarginBytes) {
    const size_t len_limit = BR_MIN(block_size - kMinMatchLen,
                                    input_size - kInputMarginBytes);
    const uint8_t* ip_limit = input + len_limit;
    uint32_t next_hash;
    for (next_hash = Hash(++ip, shift);;) {
      uint32_t skip = 32;
      const uint8_t* next_ip = ip;
      const uint8_t* candidate;
    trawl:
      do {
        uint32_t hash = next_hash;
        uint32_t bytes_between_hash_lookups = skip++ >> 5;
        ip = next_ip;
        next_ip = ip + bytes_between_hash_lookups;
        if (next_ip > ip_limit) goto emit_remainder;
        next_hash = Hash(next_ip, shift);
        candidate = ip - last_distance;
        if (IsMatch(ip, candidate)) {
          if (candidate < ip) {
            table[hash] = (int)(ip - base_ip);
            break;
          }
        }
        candidate = base_ip + table[hash];
        table[hash] = (int)(ip - base_ip);
      } while (!IsMatch(ip, candidate));

      if (ip - candidate > MAX_DISTANCE) goto trawl;

      {
        const uint8_t* base = ip;
        size_t matched = 5 + FindMatchLengthWithLimit(
                                 candidate + 5, ip + 5, (size_t)(ip_end - ip) - 5);
        int distance = (int)(base - candidate);
        size_t insert = (size_t)(base - next_emit);
        ip += matched;
        if (insert < 6210) {
          EmitInsertLen(insert, cmd_depth, cmd_bits, cmd_histo, storage_ix,
                        storage);
        } else if (ShouldUseUncompressedMode(metablock_start, next_emit, insert,
                                             literal_ratio)) {
          EmitUncompressedMetaBlock(metablock_start, base, mlen_storage_ix - 3,
                                    storage_ix, storage);
          input_size -= (size_t)(base - input);
          input = base;
          next_emit = input;
          goto next_block;
        } else {
          EmitLongInsertLen(insert, cmd_depth, cmd_bits, cmd_histo, storage_ix,
                            storage);
        }
        EmitLiterals(next_emit, insert, lit_depth, lit_bits, storage_ix,
                     storage);
        if (distance == last_distance) {
          WriteBits(cmd_depth[64], cmd_bits[64], storage_ix, storage);
          ++cmd_histo[64];
        } else {
          EmitDistance((size_t)distance, cmd_depth, cmd_bits, cmd_histo,
                       storage_ix, storage);
          last_distance = distance;
        }
        EmitCopyLenLastDistance(matched, cmd_depth, cmd_bits, cmd_histo,
                                storage_ix, storage);
        next_emit = ip;
        if (ip >= ip_limit) goto emit_remainder;
        {
          uint64_t input_bytes = Load64(ip - 3);
          uint32_t prev_hash = HashBytesAtOffset(input_bytes, 0, shift);
          uint32_t cur_hash = HashBytesAtOffset(input_bytes, 3, shift);
          table[prev_hash] = (int)(ip - base_ip - 3);
          prev_hash = HashBytesAtOffset(input_bytes, 1, shift);
          table[prev_hash] = (int)(ip - base_ip - 2);
          prev_hash = HashBytesAtOffset(input_bytes, 2, shift);
          table[prev_hash] = (int)(ip - base_ip - 1);
          candidate = base_ip + table[cur_hash];
          table[cur_hash] = (int)(ip - base_ip);
        }
      }

      while (IsMatch(ip, candidate)) {
        const uint8_t* base = ip;
        size_t matched = 5 + FindMatchLengthWithLimit(
                                 candidate + 5, ip + 5, (size_t)(ip_end - ip) - 5);
        if (ip - candidate > MAX_DISTANCE) break;
        ip += matched;
        last_distance = (int)(base - candidate);
        EmitCopyLen(matched, cmd_depth, cmd_bits, cmd_histo, storage_ix,
                    storage);
        EmitDistance((size_t)last_distance, cmd_depth, cmd_bits, cmd_histo,
                     storage_ix, storage);
        next_emit = ip;
        if (ip >= ip_limit) goto emit_remainder;
        {
          uint64_t input_bytes = Load64(ip - 3);
          uint32_t prev_hash = HashBytesAtOffset(input_bytes, 0, shift);
          uint32_t cur_hash = HashBytesAtOffset(input_bytes, 3, shift);
          table[prev_hash] = (int)(ip - base_ip - 3);
          prev_hash = HashBytesAtOffset(input_bytes, 1, shift);
          table[prev_hash] = (int)(ip - base_ip - 2);
          prev_hash = HashBytesAtOffset(input_bytes, 2, shift);
          table[prev_hash] = (int)(ip - base_ip - 1);
          candidate = base_ip + table[cur_hash];
          table[cur_hash] = (int)(ip - base_ip);
        }
      }
      next_hash = Hash(++ip, shift);
    }
  }

emit_remainder:
  input += block_size;
  input_size -= block_size;
  block_size = BR_MIN(input_size, kMergeBlockSize);
  if (input_size > 0 && total_block_size + block_size <= (1 << 20) &&
      ShouldMergeBlock(s, input, block_size, lit_depth)) {
    total_block_size += block_size;
    UpdateBits(20, (uint32_t)(total_block_size - 1), mlen_storage_ix, storage);
    goto emit_commands;
  }
  if (next_emit < ip_end) {
    const size_t insert = (size_t)(ip_end - next_emit);
    if (insert < 6210) {
