  if (input_size > 0) {
    metablock_start = input;
    block_size = BR_MIN(input_size, kFirstBlockSize);
    total_block_size = block_size;
    mlen_storage_ix = *storage_ix + 3;
    StoreMetaBlockHeader(block_size, 0, storage_ix, storage);
    WriteBits(13, 0, storage_ix, storage);
    literal_ratio = BuildAndStoreLiteralPrefixCode(s, input, block_size,
                                                   lit_depth, lit_bits,
                                                   storage_ix, storage);
    BuildAndStoreCommandPrefixCode(s, storage_ix, storage);
    goto emit_commands;
  }

  if (!is_last) {
    s->cmd_code[0] = 0;
    s->cmd_code_numbits = 0;
    BuildAndStoreCommandPrefixCode(s, &s->cmd_code_numbits, s->cmd_code);
  }
}

void BrCompressFragmentFast(BrOnePassArena* s, const uint8_t* input,
                            size_t input_size, int is_last, int* table,
                            size_t table_size, size_t* storage_ix,
                            uint8_t* storage) {
  const size_t initial_storage_ix = *storage_ix;
  const size_t table_bits = Log2FloorNonZero(table_size);
  if (input_size == 0) {
    WriteBits(1, 1, storage_ix, storage);
    WriteBits(1, 1, storage_ix, storage);
    *storage_ix = (*storage_ix + 7u) & ~7u;
    return;
  }
  CompressFragmentFastImpl(s, input, input_size, is_last, table, table_bits,
                           storage_ix, storage);
  if (*storage_ix - initial_storage_ix > 31 + (input_size << 3)) {
    EmitUncompressedMetaBlock(input, input + input_size, initial_storage_ix,
                              storage_ix, storage);
  }
  if (is_last) {
    WriteBits(1, 1, storage_ix, storage);
    WriteBits(1, 1, storage_ix, storage);
    *storage_ix = (*storage_ix + 7u) & ~7u;
  }
