#ifndef BR_RINGBUFFER_H_
#define BR_RINGBUFFER_H_
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
  uint32_t size_;
  uint32_t mask_;
  uint32_t tail_size_;
  uint32_t total_size_;
  uint32_t cur_size_;
  uint32_t pos_;
  uint8_t* data_;
  uint8_t* buffer_;
} BrRingBuffer;

static inline void RingBufferInit(BrRingBuffer* rb) {
  rb->cur_size_ = 0;
  rb->pos_ = 0;
  rb->data_ = 0;
  rb->buffer_ = 0;
}

static inline void RingBufferSetup(int window_bits, int tail_bits,
                                   BrRingBuffer* rb) {
  rb->size_ = 1u << window_bits;
  rb->mask_ = (1u << window_bits) - 1;
  rb->tail_size_ = 1u << tail_bits;
  rb->total_size_ = rb->size_ + rb->tail_size_;
}

static inline void RingBufferFree(BrRingBuffer* rb) { free(rb->data_); }

static inline void RingBufferInitBuffer(const uint32_t buflen,
                                        BrRingBuffer* rb) {
  static const size_t kSlack = 7;
  uint8_t* new_data = (uint8_t*)malloc(2 + buflen + kSlack);
  size_t i;
  if (rb->data_) {
