/* Streaming encoder state machine. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "bit_stream.h"
#include "command.h"
#include "enc_common.h"
#include "encode.h"
#include "encoder_internal.h"
#include "fragment.h"
#include "ringbuffer.h"
#include "pipeline.h"

#define STREAM_PROCESSING 0
#define STREAM_FLUSH_REQUESTED 1
#define STREAM_FINISHED 2
#define STREAM_METADATA_HEAD 3
#define STREAM_METADATA_BODY 4

struct BrEncoder {
  BrEncoderParams params;
  BrPipeline* pipe; /* q2+ state (hasher, commands...) */
  uint64_t input_pos_;
  BrRingBuffer ringbuffer_;
  size_t cmd_alloc_size_;
  Command* commands_;
  size_t num_commands_;
  size_t num_literals_;
  size_t last_insert_len_;
  uint64_t last_flush_pos_;
  uint64_t last_processed_pos_;
  int dist_cache_[16];
  int saved_dist_cache_[4];
  uint16_t last_bytes_;
  uint8_t last_bytes_bits_;
  uint8_t prev_byte_;
  uint8_t prev_byte2_;
  size_t storage_size_;
  uint8_t* storage_;
  int small_table_[1 << 10];
  int* large_table_;
  size_t large_table_size_;
  BrOnePassArena* one_pass_arena_;
  BrTwoPassArena* two_pass_arena_;
  uint32_t* command_buf_;
  uint8_t* literal_buf_;
  uint8_t* next_out_;
  size_t available_out_;
  size_t total_out_;
  uint8_t tiny_buf_[16];
  uint32_t remaining_metadata_bytes_;
  int stream_state_;
  int is_last_block_emitted_;
  int is_initialized_;
};

BrEncoder* BrEncCreate(void) {
  BrEncoder* s = (BrEncoder*)calloc(1, sizeof(BrEncoder));
  if (!s) return NULL;
  BrInitLog2Table();
  s->params.quality = 11;
  s->params.lgwin = 22;
  s->params.lgblock = 0;
  s->params.size_hint = 0;
  s->params.large_window = 0;
  s->params.dist.distance_postfix_bits = 0;
  s->params.dist.num_direct_distance_codes = 0;
  s->params.dist.alphabet_size_max = BR_DISTANCE_ALPHABET_SIZE(0, 0, 24);
  s->params.dist.alphabet_size_limit = s->params.dist.alphabet_size_max;
  s->params.dist.max_distance = 0x3FFFFFC;
  RingBufferInit(&s->ringbuffer_);
  s->remaining_metadata_bytes_ = 0xFFFFFFFFu;
  s->dist_cache_[0] = 4;
  s->dist_cache_[1] = 11;
  s->dist_cache_[2] = 15;
  s->dist_cache_[3] = 16;
  memcpy(s->saved_dist_cache_, s->dist_cache_, sizeof(s->saved_dist_cache_));
  return s;
}

void BrEncDestroy(BrEncoder* s) {
  if (!s) return;
  free(s->commands_);
  RingBufferFree(&s->ringbuffer_);
  if (s->pipe) BrPipelineDestroy(s->pipe);
  free(s->storage_);
  free(s->large_table_);
  free(s->one_pass_arena_);
  free(s->two_pass_arena_);
  free(s->command_buf_);
  free(s->literal_buf_);
  free(s);
}

void BrEncSetParam(BrEncoder* s, int param, uint32_t value) {
  if (s->is_initialized_) return;
  switch (param) {
    case BRE_PARAM_QUALITY: s->params.quality = (int)value; break;
    case BRE_PARAM_LGWIN: s->params.lgwin = (int)value; break;
    case BRE_PARAM_LARGE_WINDOW: s->params.large_window = value ? 1 : 0; break;
    case BRE_PARAM_SIZE_HINT: s->params.size_hint = value; break;
    default: break;
  }
}

int BrEncAttachRawDictionary(BrEncoder* s, const uint8_t* data, size_t size) {
  s->params.dict = data;
  s->params.dict_len = size;
  return 1;
}

void BrInitDistanceParams(BrDistanceParams* dist_params, uint32_t npostfix,
                          uint32_t ndirect, int large_window) {
  uint32_t alphabet_size_max;
  uint32_t alphabet_size_limit;
  uint32_t max_distance;
  dist_params->distance_postfix_bits = npostfix;
  dist_params->num_direct_distance_codes = ndirect;
  alphabet_size_max = BR_DISTANCE_ALPHABET_SIZE(npostfix, ndirect, 24);
  alphabet_size_limit = alphabet_size_max;
  max_distance = ndirect + (1U << (24 + npostfix + 2)) - (1U << (npostfix + 2));
  if (large_window) {
    /* BrotliCalculateDistanceCodeLimit(BR_MAX_ALLOWED_DISTANCE, ...) */
    uint32_t md = BR_MAX_ALLOWED_DISTANCE;
    if (md <= ndirect) {
      alphabet_size_limit = md + 16;
      max_distance = md;
    } else {
      uint32_t forbidden_distance = md + 1;
      uint32_t offset = forbidden_distance - ndirect - 1;
      uint32_t ndistbits = 0;
      uint32_t tmp, half, group, postfix = (1u << npostfix) - 1, extra, start;
      offset = (offset >> npostfix) + 4;
      tmp = offset / 2;
      while (tmp != 0) {
        ndistbits++;
        tmp = tmp >> 1;
      }
      ndistbits--;
      half = (offset >> ndistbits) & 1;
      group = ((ndistbits - 1) << 1) | half;
      if (group == 0) {
        alphabet_size_limit = ndirect + 16;
        max_distance = ndirect;
      } else {
        group--;
        ndistbits = (group >> 1) + 1;
        extra = (1u << ndistbits) - 1;
        start = (1u << (ndistbits + 1)) - 4;
        start += (group & 1) << ndistbits;
        max_distance = ((start + extra) << npostfix) + postfix + ndirect + 1;
        alphabet_size_limit =
            ((group << npostfix) | postfix) + ndirect + 16 + 1;
      }
    }
    alphabet_size_max = BR_DISTANCE_ALPHABET_SIZE(npostfix, ndirect, 62);
  }
  dist_params->alphabet_size_max = alphabet_size_max;
  dist_params->alphabet_size_limit = alphabet_size_limit;
  dist_params->max_distance = max_distance;
}

static void SanitizeParams(BrEncoderParams* params) {
  if (params->quality < 0) params->quality = 0;
  if (params->quality > 11) params->quality = 11;
  if (params->quality <= 2) params->large_window = 0;
  if (params->lgwin < 10) {
    params->lgwin = 10;
  } else {
    int max_lgwin = params->large_window ? 30 : 24;
    if (params->lgwin > max_lgwin) params->lgwin = max_lgwin;
  }
}

static int ComputeLgBlock(const BrEncoderParams* params) {
  int lgblock = params->lgblock;
  if (params->quality == 0 || params->quality == 1) {
    lgblock = params->lgwin;
  } else if (params->quality < 4) {
    lgblock = 14;
  } else if (lgblock == 0) {
    lgblock = 16;
    if (params->quality >= 9 && params->lgwin > lgblock) {
      lgblock = BR_MIN(18, params->lgwin);
    }
  } else {
    lgblock = BR_MIN(24, BR_MAX(16, lgblock));
  }
  return lgblock;
}

static int ComputeRbBits(const BrEncoderParams* params) {
  return 1 + BR_MAX(params->lgwin, params->lgblock);
}

static size_t MaxMetablockSize(const BrEncoderParams* params) {
  int bits = BR_MIN(ComputeRbBits(params), 24);
  return (size_t)1 << bits;
}

static void EncodeWindowBits(int lgwin, int large_window, uint16_t* last_bytes,
                             uint8_t* last_bytes_bits) {
  if (large_window) {
    *last_bytes = (uint16_t)(((lgwin & 0x3F) << 8) | 0x11);
    *last_bytes_bits = 14;
  } else {
    if (lgwin == 16) {
      *last_bytes = 0;
      *last_bytes_bits = 1;
    } else if (lgwin == 17) {
      *last_bytes = 1;
      *last_bytes_bits = 7;
    } else if (lgwin > 17) {
      *last_bytes = (uint16_t)(((lgwin - 17) << 1) | 0x01);
      *last_bytes_bits = 4;
    } else {
      *last_bytes = (uint16_t)(((lgwin - 8) << 4) | 0x01);
      *last_bytes_bits = 7;
    }
  }
}

static void ChooseDistanceParams(BrEncoderParams* params) {
  uint32_t distance_postfix_bits = 0;
  uint32_t num_direct_distance_codes = 0;
  if (params->quality >= 4) {
    uint32_t ndirect_msb;
    distance_postfix_bits = params->dist.distance_postfix_bits;
    num_direct_distance_codes = params->dist.num_direct_distance_codes;
    ndirect_msb = (num_direct_distance_codes >> distance_postfix_bits) & 0x0F;
    if (distance_postfix_bits > 3 || num_direct_distance_codes > 120 ||
        (ndirect_msb << distance_postfix_bits) != num_direct_distance_codes) {
      distance_postfix_bits = 0;
      num_direct_distance_codes = 0;
    }
  }
  BrInitDistanceParams(&params->dist, distance_postfix_bits,
                       num_direct_distance_codes, params->large_window);
}

static int EnsureInitialized(BrEncoder* s) {
  if (s->is_initialized_) return 1;
  s->last_bytes_bits_ = 0;
  s->last_bytes_ = 0;
  s->remaining_metadata_bytes_ = 0xFFFFFFFFu;
  SanitizeParams(&s->params);
  s->params.lgblock = ComputeLgBlock(&s->params);
  ChooseDistanceParams(&s->params);
  RingBufferSetup(ComputeRbBits(&s->params), s->params.lgblock,
                  &s->ringbuffer_);
  {
    int lgwin = s->params.lgwin;
    if (s->params.quality == 0 || s->params.quality == 1) {
      lgwin = BR_MAX(lgwin, 18);
    }
    EncodeWindowBits(lgwin, s->params.large_window, &s->last_bytes_,
                     &s->last_bytes_bits_);
  }
  if (s->params.quality == 0) {
    s->one_pass_arena_ = (BrOnePassArena*)calloc(1, sizeof(BrOnePassArena));
    BrInitCommandPrefixCodes(s->one_pass_arena_);
  } else if (s->params.quality == 1) {
    s->two_pass_arena_ = (BrTwoPassArena*)calloc(1, sizeof(BrTwoPassArena));
  }
  s->is_initialized_ = 1;
  return 1;
}

static uint8_t* GetBrotliStorage(BrEncoder* s, size_t size) {
  if (s->storage_size_ < size) {
    free(s->storage_);
    s->storage_ = (uint8_t*)malloc(size + 16);
    s->storage_size_ = size;
  }
  return s->storage_;
}

static size_t HashTableSize(size_t max_table_size, size_t input_size) {
  size_t htsize = 256;
  while (htsize < max_table_size && htsize < input_size) htsize <<= 1;
  return htsize;
}

static int* GetHashTable(BrEncoder* s, int quality, size_t input_size,
                         size_t* table_size) {
  const size_t max_table_size = quality == 0 ? (1 << 15) : (1 << 17);
  size_t htsize = HashTableSize(max_table_size, input_size);
  int* table;
  if (quality == 0) {
    if ((htsize & 0xAAAAA) == 0) htsize <<= 1;
  }
  if (htsize <= sizeof(s->small_table_) / sizeof(s->small_table_[0])) {
    table = s->small_table_;
  } else {
    if (htsize > s->large_table_size_) {
      s->large_table_size_ = htsize;
      free(s->large_table_);
      s->large_table_ = (int*)malloc(htsize * sizeof(int));
    }
    table = s->large_table_;
  }
  *table_size = htsize;
  memset(table, 0, htsize * sizeof(*table));
  return table;
}

static uint64_t UnprocessedInputSize(BrEncoder* s) {
  return s->input_pos_ - s->last_processed_pos_;
}

static size_t RemainingInputBlockSize(BrEncoder* s) {
  const uint64_t delta = UnprocessedInputSize(s);
  size_t block_size = (size_t)1 << s->params.lgblock;
  if (delta >= block_size) return 0;
  return block_size - (size_t)delta;
}

static uint32_t WrapPosition(uint64_t position) {
  uint32_t result = (uint32_t)position;
  uint64_t gb = position >> 30;
  if (gb > 2) {
    result = (result & ((1u << 30) - 1)) |
             ((uint32_t)((gb - 1) & 1) + 1) << 30;
  }
  return result;
}

static int UpdateLastProcessedPos(BrEncoder* s) {
  uint32_t wrapped_last_processed_pos = WrapPosition(s->last_processed_pos_);
  uint32_t wrapped_input_pos = WrapPosition(s->input_pos_);
  s->last_processed_pos_ = s->input_pos_;
  return wrapped_input_pos < wrapped_last_processed_pos;
}

static void CopyInputToRingBuffer(BrEncoder* s, const size_t input_size,
                                  const uint8_t* input_buffer) {
  BrRingBuffer* ringbuffer_ = &s->ringbuffer_;
  RingBufferWrite(input_buffer, input_size, ringbuffer_);
  s->input_pos_ += input_size;
  if (ringbuffer_->pos_ <= ringbuffer_->mask_) {
    memset(ringbuffer_->buffer_ + ringbuffer_->pos_, 0, 7);
  }
}

static void UpdateSizeHint(BrEncoder* s, size_t available_in) {
  if (s->params.size_hint == 0) {
    uint64_t delta = UnprocessedInputSize(s);
    uint64_t tail = available_in;
    uint32_t limit = 1u << 30;
    uint32_t total;
    if ((delta >= limit) || (tail >= limit) || ((delta + tail) >= limit)) {
      total = limit;
    } else {
      total = (uint32_t)(delta + tail);
    }
    s->params.size_hint = total;
  }
}

static int EncodeData(BrEncoder* s, const int is_last, const int force_flush,
                      size_t* out_size, uint8_t** output) {
  const uint64_t delta = UnprocessedInputSize(s);
  uint32_t bytes = (uint32_t)delta;
  uint32_t wrapped_last_processed_pos = WrapPosition(s->last_processed_pos_);
  uint8_t* data;
  uint32_t mask;
  int literal_context_mode;

  data = s->ringbuffer_.buffer_;
  mask = s->ringbuffer_.mask_;

  if (delta == 0) {
    if (!data) {
      if (is_last) {
        s->last_bytes_ |= (uint16_t)(3u << s->last_bytes_bits_);
        s->last_bytes_bits_ = (uint8_t)(s->last_bytes_bits_ + 2u);
        s->tiny_buf_[0] = (uint8_t)s->last_bytes_;
        s->tiny_buf_[1] = (uint8_t)(s->last_bytes_ >> 8);
        *output = s->tiny_buf_;
        *out_size = (s->last_bytes_bits_ + 7u) >> 3u;
        return 1;
      } else {
        *out_size = 0;
        return 1;
      }
    }
  }

  if (s->is_last_block_emitted_) return 0;
  if (is_last) s->is_last_block_emitted_ = 1;

  if (delta > ((size_t)1 << s->params.lgblock)) return 0;

  if (!s->pipe) s->pipe = BrPipelineCreate();

  {
    size_t newsize = s->num_commands_ + bytes / 2 + 1;
    if (newsize > s->cmd_alloc_size_) {
      Command* new_commands;
      newsize += (bytes / 4) + 16;
      s->cmd_alloc_size_ = newsize;
      new_commands = (Command*)malloc(sizeof(Command) * newsize);
      if (s->commands_) {
        memcpy(new_commands, s->commands_, sizeof(Command) * s->num_commands_);
        free(s->commands_);
      }
      s->commands_ = new_commands;
    }
  }

  BrPipelineInitOrStitch(s->pipe, data, mask, &s->params,
                         wrapped_last_processed_pos, bytes, is_last);

  literal_context_mode = BrChooseContextMode(
      &s->params, data, WrapPosition(s->last_flush_pos_), mask,
      (size_t)(s->input_pos_ - s->last_flush_pos_));

  if (s->num_commands_ && s->last_insert_len_ == 0) {
    BrExtendLastCommand(&s->params, s->commands_, s->num_commands_, data, mask,
                        s->last_processed_pos_, s->dist_cache_, &bytes,
                        &wrapped_last_processed_pos);
  }

  BrPipelineCreateBackwardReferences(
      s->pipe, bytes, wrapped_last_processed_pos, data, mask,
      literal_context_mode, &s->params, s->dist_cache_, &s->last_insert_len_,
      &s->commands_[s->num_commands_], &s->num_commands_, &s->num_literals_);

  {
    const size_t max_length = MaxMetablockSize(&s->params);
    const size_t max_literals = max_length / 8;
    const size_t max_commands = max_length / 8;
    const size_t processed_bytes = (size_t)(s->input_pos_ - s->last_flush_pos_);
    const int next_input_fits_metablock =
        processed_bytes + ((size_t)1 << s->params.lgblock) <= max_length;
    const int should_flush = s->params.quality < 4 &&
                             s->num_literals_ + s->num_commands_ >= 0x2FFF;
    if (!is_last && !force_flush && !should_flush &&
        next_input_fits_metablock && s->num_literals_ < max_literals &&
        s->num_commands_ < max_commands) {
      if (UpdateLastProcessedPos(s)) {
        BrPipelineHasherReset(s->pipe);
      }
      *out_size = 0;
      return 1;
    }
  }

  if (s->last_insert_len_ > 0) {
    InitInsertCommand(&s->commands_[s->num_commands_++], s->last_insert_len_);
    s->num_literals_ += s->last_insert_len_;
    s->last_insert_len_ = 0;
  }

  if (!is_last && s->input_pos_ == s->last_flush_pos_) {
    *out_size = 0;
    return 1;
  }
  {
    const uint32_t metablock_size =
        (uint32_t)(s->input_pos_ - s->last_flush_pos_);
    uint8_t* storage = GetBrotliStorage(s, 2 * metablock_size + 503);
    size_t storage_ix = s->last_bytes_bits_;
    storage[0] = (uint8_t)s->last_bytes_;
    storage[1] = (uint8_t)(s->last_bytes_ >> 8);
    BrWriteMetaBlockInternal(data, mask, s->last_flush_pos_, metablock_size,
                             is_last, literal_context_mode, &s->params,
                             s->prev_byte_, s->prev_byte2_, s->num_literals_,
                             s->num_commands_, s->commands_,
                             s->saved_dist_cache_, s->dist_cache_, &storage_ix,
                             storage);
    s->last_bytes_ = (uint16_t)(storage[storage_ix >> 3]);
    s->last_bytes_bits_ = storage_ix & 7u;
    s->last_flush_pos_ = s->input_pos_;
    if (UpdateLastProcessedPos(s)) {
      BrPipelineHasherReset(s->pipe);
    }
    if (s->last_flush_pos_ > 0) {
      s->prev_byte_ = data[((uint32_t)s->last_flush_pos_ - 1) & mask];
    }
    if (s->last_flush_pos_ > 1) {
      s->prev_byte2_ = data[(uint32_t)(s->last_flush_pos_ - 2) & mask];
    }
    s->num_commands_ = 0;
    s->num_literals_ = 0;
    memcpy(s->saved_dist_cache_, s->dist_cache_, sizeof(s->saved_dist_cache_));
    *output = storage;
    *out_size = storage_ix >> 3;
    return 1;
  }
}

static size_t WriteMetadataHeader(BrEncoder* s, const size_t block_size,
                                  uint8_t* header) {
  size_t storage_ix;
  storage_ix = s->last_bytes_bits_;
  header[0] = (uint8_t)s->last_bytes_;
  header[1] = (uint8_t)(s->last_bytes_ >> 8);
  s->last_bytes_ = 0;
  s->last_bytes_bits_ = 0;
  WriteBits(1, 0, &storage_ix, header);
  WriteBits(2, 3, &storage_ix, header);
  WriteBits(1, 0, &storage_ix, header);
  if (block_size == 0) {
    WriteBits(2, 0, &storage_ix, header);
  } else {
    uint32_t nbits = (block_size == 1)
                         ? 1
                         : (Log2FloorNonZero((uint32_t)block_size - 1) + 1);
    uint32_t nbytes = (nbits + 7) / 8;
    WriteBits(2, nbytes, &storage_ix, header);
    WriteBits(8 * nbytes, block_size - 1, &storage_ix, header);
  }
  return (storage_ix + 7u) >> 3;
}

static void InjectBytePaddingBlock(BrEncoder* s) {
  uint32_t seal = s->last_bytes_;
  size_t seal_bits = s->last_bytes_bits_;
  uint8_t* destination;
  s->last_bytes_ = 0;
  s->last_bytes_bits_ = 0;
  seal |= 0x6u << seal_bits;
  seal_bits += 6;
  if (s->next_out_) {
    destination = s->next_out_ + s->available_out_;
  } else {
    destination = s->tiny_buf_;
    s->next_out_ = destination;
  }
  destination[0] = (uint8_t)seal;
  if (seal_bits > 8) destination[1] = (uint8_t)(seal >> 8);
  if (seal_bits > 16) destination[2] = (uint8_t)(seal >> 16);
  s->available_out_ += (seal_bits + 7) >> 3;
}

static int InjectFlushOrPushOutput(BrEncoder* s, size_t* available_out,
                                   uint8_t** next_out) {
  if (s->stream_state_ == STREAM_FLUSH_REQUESTED && s->last_bytes_bits_ != 0) {
    InjectBytePaddingBlock(s);
    return 1;
  }
  if (s->available_out_ != 0 && *available_out != 0) {
    size_t copy_output_size = BR_MIN(s->available_out_, *available_out);
    memcpy(*next_out, s->next_out_, copy_output_size);
    *next_out += copy_output_size;
    *available_out -= copy_output_size;
    s->next_out_ += copy_output_size;
    s->available_out_ -= copy_output_size;
    s->total_out_ += copy_output_size;
    return 1;
  }
  return 0;
}

static void CheckFlushComplete(BrEncoder* s) {
  if (s->stream_state_ == STREAM_FLUSH_REQUESTED && s->available_out_ == 0) {
    s->stream_state_ = STREAM_PROCESSING;
    s->next_out_ = 0;
  }
}

static int CompressStreamFast(BrEncoder* s, int op, size_t* available_in,
                              const uint8_t** next_in, size_t* available_out,
                              uint8_t** next_out) {
  const size_t block_size_limit = (size_t)1 << s->params.lgwin;
  const size_t buf_size = BR_MIN((size_t)BR_TWO_PASS_BLOCK_SIZE,
                                 BR_MIN(*available_in, block_size_limit));
  uint32_t* tmp_command_buf = NULL;
  uint32_t* command_buf = NULL;
  uint8_t* tmp_literal_buf = NULL;
  uint8_t* literal_buf = NULL;
  if (s->params.quality == 1) {
    if (!s->command_buf_ && buf_size == BR_TWO_PASS_BLOCK_SIZE) {
      s->command_buf_ =
          (uint32_t*)malloc(sizeof(uint32_t) * BR_TWO_PASS_BLOCK_SIZE);
      s->literal_buf_ = (uint8_t*)malloc(BR_TWO_PASS_BLOCK_SIZE);
    }
    if (s->command_buf_) {
      command_buf = s->command_buf_;
      literal_buf = s->literal_buf_;
    } else {
      tmp_command_buf = (uint32_t*)malloc(sizeof(uint32_t) * (buf_size + 1));
      tmp_literal_buf = (uint8_t*)malloc(buf_size + 1);
      command_buf = tmp_command_buf;
      literal_buf = tmp_literal_buf;
    }
  }
  for (;;) {
    if (InjectFlushOrPushOutput(s, available_out, next_out)) continue;
    if (s->available_out_ == 0 && s->stream_state_ == STREAM_PROCESSING &&
        (*available_in != 0 || op != BRE_OP_PROCESS)) {
      size_t block_size = BR_MIN(block_size_limit, *available_in);
      int is_last = (*available_in == block_size) && (op == BRE_OP_FINISH);
      int force_flush = (*available_in == block_size) && (op == BRE_OP_FLUSH);
      size_t max_out_size = 2 * block_size + 503;
      int inplace = 1;
      uint8_t* storage = NULL;
      size_t storage_ix = s->last_bytes_bits_;
      size_t table_size;
      int* table;
      if (force_flush && block_size == 0) {
        s->stream_state_ = STREAM_FLUSH_REQUESTED;
        continue;
      }
      if (max_out_size + 16 <= *available_out) {
        storage = *next_out;
      } else {
        inplace = 0;
        storage = GetBrotliStorage(s, max_out_size);
      }
      storage[0] = (uint8_t)s->last_bytes_;
      storage[1] = (uint8_t)(s->last_bytes_ >> 8);
      table = GetHashTable(s, s->params.quality, block_size, &table_size);
      if (s->params.quality == 0) {
        BrCompressFragmentFast(s->one_pass_arena_, *next_in, block_size,
                               is_last, table, table_size, &storage_ix,
                               storage);
      } else {
        BrCompressFragmentTwoPass(s->two_pass_arena_, *next_in, block_size,
                                  is_last, command_buf, literal_buf, table,
                                  table_size, &storage_ix, storage);
      }
      if (block_size != 0) {
        *next_in += block_size;
        *available_in -= block_size;
      }
      if (inplace) {
        size_t out_bytes = storage_ix >> 3;
        *next_out += out_bytes;
        *available_out -= out_bytes;
        s->total_out_ += out_bytes;
      } else {
        size_t out_bytes = storage_ix >> 3;
        s->next_out_ = storage;
        s->available_out_ = out_bytes;
      }
      s->last_bytes_ = (uint16_t)(storage[storage_ix >> 3]);
      s->last_bytes_bits_ = storage_ix & 7u;
      if (force_flush) s->stream_state_ = STREAM_FLUSH_REQUESTED;
      if (is_last) s->stream_state_ = STREAM_FINISHED;
      continue;
    }
    break;
  }
  free(tmp_command_buf);
  free(tmp_literal_buf);
  CheckFlushComplete(s);
  return 1;
}

static int ProcessMetadata(BrEncoder* s, size_t* available_in,
                           const uint8_t** next_in, size_t* available_out,
                           uint8_t** next_out) {
  if (*available_in > (1u << 24)) return 0;
  if (s->stream_state_ == STREAM_PROCESSING) {
    s->remaining_metadata_bytes_ = (uint32_t)*available_in;
    s->stream_state_ = STREAM_METADATA_HEAD;
  }
  if (s->stream_state_ != STREAM_METADATA_HEAD &&
      s->stream_state_ != STREAM_METADATA_BODY) {
    return 0;
  }
  for (;;) {
    if (InjectFlushOrPushOutput(s, available_out, next_out)) continue;
    if (s->available_out_ != 0) break;
    if (s->input_pos_ != s->last_flush_pos_) {
      int result =
          EncodeData(s, 0, 1, &s->available_out_, &s->next_out_);
      if (!result) return 0;
      continue;
    }
    if (s->stream_state_ == STREAM_METADATA_HEAD) {
      s->next_out_ = s->tiny_buf_;
      s->available_out_ =
          WriteMetadataHeader(s, s->remaining_metadata_bytes_, s->next_out_);
      s->stream_state_ = STREAM_METADATA_BODY;
      continue;
    } else {
      if (s->remaining_metadata_bytes_ == 0) {
        s->remaining_metadata_bytes_ = 0xFFFFFFFFu;
        s->stream_state_ = STREAM_PROCESSING;
        break;
      }
      if (*available_out) {
        uint32_t copy =
            (uint32_t)BR_MIN((size_t)s->remaining_metadata_bytes_, *available_out);
        memcpy(*next_out, *next_in, copy);
        *next_in += copy;
        *available_in -= copy;
        s->remaining_metadata_bytes_ -= copy;
        *next_out += copy;
        *available_out -= copy;
      } else {
        uint32_t copy = BR_MIN(s->remaining_metadata_bytes_, 16u);
        s->next_out_ = s->tiny_buf_;
        memcpy(s->next_out_, *next_in, copy);
        *next_in += copy;
        *available_in -= copy;
        s->remaining_metadata_bytes_ -= copy;
        s->available_out_ = copy;
      }
      continue;
    }
  }
  return 1;
}

int BrEncCompressStream(BrEncoder* s, int op, size_t* available_in,
                        const uint8_t** next_in, size_t* available_out,
                        uint8_t** next_out) {
  if (!EnsureInitialized(s)) return 0;
  if (s->remaining_metadata_bytes_ != 0xFFFFFFFFu) {
    if (*available_in != s->remaining_metadata_bytes_) return 0;
    if (op != BRE_OP_EMIT_METADATA) return 0;
  }
  if (op == BRE_OP_EMIT_METADATA) {
    UpdateSizeHint(s, 0);
    return ProcessMetadata(s, available_in, next_in, available_out, next_out);
  }
  if (s->stream_state_ == STREAM_METADATA_HEAD ||
      s->stream_state_ == STREAM_METADATA_BODY) {
    return 0;
  }
  if (s->stream_state_ != STREAM_PROCESSING && *available_in != 0) return 0;
  if (s->params.quality == 0 || s->params.quality == 1) {
    return CompressStreamFast(s, op, available_in, next_in, available_out,
                              next_out);
  }
  for (;;) {
    size_t remaining_block_size = RemainingInputBlockSize(s);
    if (remaining_block_size != 0 && *available_in != 0) {
      size_t copy_input_size = BR_MIN(remaining_block_size, *available_in);
      CopyInputToRingBuffer(s, copy_input_size, *next_in);
      *next_in += copy_input_size;
      *available_in -= copy_input_size;
      continue;
    }
    if (InjectFlushOrPushOutput(s, available_out, next_out)) continue;
    if (s->available_out_ == 0 && s->stream_state_ == STREAM_PROCESSING) {
      if (remaining_block_size == 0 || op != BRE_OP_PROCESS) {
        int is_last = (*available_in == 0) && op == BRE_OP_FINISH;
        int force_flush = (*available_in == 0) && op == BRE_OP_FLUSH;
        int result;
        UpdateSizeHint(s, *available_in);
        result = EncodeData(s, is_last, force_flush, &s->available_out_,
                            &s->next_out_);
        if (!result) return 0;
        if (force_flush) s->stream_state_ = STREAM_FLUSH_REQUESTED;
        if (is_last) s->stream_state_ = STREAM_FINISHED;
        continue;
      }
    }
    break;
  }
  CheckFlushComplete(s);
  return 1;
}

int BrEncIsFinished(BrEncoder* s) {
  return s->stream_state_ == STREAM_FINISHED && s->available_out_ == 0;
}

int BrEncHasMoreOutput(BrEncoder* s) { return s->available_out_ != 0; }
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > encoder.c <<'EOF'
/* Streaming encoder state machine. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "bit_stream.h"
#include "command.h"
#include "enc_common.h"
#include "encode.h"
#include "encoder_internal.h"
#include "fragment.h"
#include "ringbuffer.h"
#include "pipeline.h"

#define STREAM_PROCESSING 0
#define STREAM_FLUSH_REQUESTED 1
#define STREAM_FINISHED 2
#define STREAM_METADATA_HEAD 3
#define STREAM_METADATA_BODY 4

struct BrEncoder {
  BrEncoderParams params;
  BrPipeline* pipe; /* q2+ state (hasher, commands...) */
  uint64_t input_pos_;
  BrRingBuffer ringbuffer_;
  size_t cmd_alloc_size_;
  Command* commands_;
  size_t num_commands_;
  size_t num_literals_;
  size_t last_insert_len_;
  uint64_t last_flush_pos_;
  uint64_t last_processed_pos_;
  int dist_cache_[16];
  int saved_dist_cache_[4];
  uint16_t last_bytes_;
  uint8_t last_bytes_bits_;
  uint8_t prev_byte_;
  uint8_t prev_byte2_;
  size_t storage_size_;
  uint8_t* storage_;
  int small_table_[1 << 10];
  int* large_table_;
  size_t large_table_size_;
  BrOnePassArena* one_pass_arena_;
  BrTwoPassArena* two_pass_arena_;
  uint32_t* command_buf_;
  uint8_t* literal_buf_;
  uint8_t* next_out_;
  size_t available_out_;
  size_t total_out_;
  uint8_t tiny_buf_[16];
  uint32_t remaining_metadata_bytes_;
  int stream_state_;
  int is_last_block_emitted_;
  int is_initialized_;
};

BrEncoder* BrEncCreate(void) {
  BrEncoder* s = (BrEncoder*)calloc(1, sizeof(BrEncoder));
  if (!s) return NULL;
  BrInitLog2Table();
  s->params.quality = 11;
  s->params.lgwin = 22;
  s->params.lgblock = 0;
  s->params.size_hint = 0;
  s->params.large_window = 0;
  s->params.dist.distance_postfix_bits = 0;
  s->params.dist.num_direct_distance_codes = 0;
  s->params.dist.alphabet_size_max = BR_DISTANCE_ALPHABET_SIZE(0, 0, 24);
  s->params.dist.alphabet_size_limit = s->params.dist.alphabet_size_max;
  s->params.dist.max_distance = 0x3FFFFFC;
  RingBufferInit(&s->ringbuffer_);
  s->remaining_metadata_bytes_ = 0xFFFFFFFFu;
  s->dist_cache_[0] = 4;
  s->dist_cache_[1] = 11;
  s->dist_cache_[2] = 15;
  s->dist_cache_[3] = 16;
  memcpy(s->saved_dist_cache_, s->dist_cache_, sizeof(s->saved_dist_cache_));
  return s;
}

void BrEncDestroy(BrEncoder* s) {
  if (!s) return;
  free(s->commands_);
  RingBufferFree(&s->ringbuffer_);
  if (s->pipe) BrPipelineDestroy(s->pipe);
  free(s->storage_);
  free(s->large_table_);
  free(s->one_pass_arena_);
  free(s->two_pass_arena_);
  free(s->command_buf_);
  free(s->literal_buf_);
  free(s);
}

void BrEncSetParam(BrEncoder* s, int param, uint32_t value) {
  if (s->is_initialized_) return;
  switch (param) {
    case BRE_PARAM_QUALITY: s->params.quality = (int)value; break;
    case BRE_PARAM_LGWIN: s->params.lgwin = (int)value; break;
    case BRE_PARAM_LARGE_WINDOW: s->params.large_window = value ? 1 : 0; break;
    case BRE_PARAM_SIZE_HINT: s->params.size_hint = value; break;
    default: break;
  }
}

int BrEncAttachRawDictionary(BrEncoder* s, const uint8_t* data, size_t size) {
  s->params.dict = data;
  s->params.dict_len = size;
  return 1;
}

void BrInitDistanceParams(BrDistanceParams* dist_params, uint32_t npostfix,
                          uint32_t ndirect, int large_window) {
  uint32_t alphabet_size_max;
  uint32_t alphabet_size_limit;
  uint32_t max_distance;
  dist_params->distance_postfix_bits = npostfix;
  dist_params->num_direct_distance_codes = ndirect;
  alphabet_size_max = BR_DISTANCE_ALPHABET_SIZE(npostfix, ndirect, 24);
  alphabet_size_limit = alphabet_size_max;
  max_distance = ndirect + (1U << (24 + npostfix + 2)) - (1U << (npostfix + 2));
  if (large_window) {
    /* BrotliCalculateDistanceCodeLimit(BR_MAX_ALLOWED_DISTANCE, ...) */
    uint32_t md = BR_MAX_ALLOWED_DISTANCE;
    if (md <= ndirect) {
      alphabet_size_limit = md + 16;
      max_distance = md;
    } else {
      uint32_t forbidden_distance = md + 1;
      uint32_t offset = forbidden_distance - ndirect - 1;
      uint32_t ndistbits = 0;
      uint32_t tmp, half, group, postfix = (1u << npostfix) - 1, extra, start;
      offset = (offset >> npostfix) + 4;
      tmp = offset / 2;
      while (tmp != 0) {
        ndistbits++;
        tmp = tmp >> 1;
      }
      ndistbits--;
      half = (offset >> ndistbits) & 1;
      group = ((ndistbits - 1) << 1) | half;
      if (group == 0) {
        alphabet_size_limit = ndirect + 16;
        max_distance = ndirect;
      } else {
        group--;
        ndistbits = (group >> 1) + 1;
        extra = (1u << ndistbits) - 1;
        start = (1u << (ndistbits + 1)) - 4;
        start += (group & 1) << ndistbits;
        max_distance = ((start + extra) << npostfix) + postfix + ndirect + 1;
        alphabet_size_limit =
            ((group << npostfix) | postfix) + ndirect + 16 + 1;
      }
    }
    alphabet_size_max = BR_DISTANCE_ALPHABET_SIZE(npostfix, ndirect, 62);
  }
  dist_params->alphabet_size_max = alphabet_size_max;
  dist_params->alphabet_size_limit = alphabet_size_limit;
  dist_params->max_distance = max_distance;
}

static void SanitizeParams(BrEncoderParams* params) {
  if (params->quality < 0) params->quality = 0;
  if (params->quality > 11) params->quality = 11;
  if (params->quality <= 2) params->large_window = 0;
  if (params->lgwin < 10) {
    params->lgwin = 10;
  } else {
    int max_lgwin = params->large_window ? 30 : 24;
    if (params->lgwin > max_lgwin) params->lgwin = max_lgwin;
  }
}

static int ComputeLgBlock(const BrEncoderParams* params) {
  int lgblock = params->lgblock;
  if (params->quality == 0 || params->quality == 1) {
    lgblock = params->lgwin;
  } else if (params->quality < 4) {
    lgblock = 14;
  } else if (lgblock == 0) {
    lgblock = 16;
    if (params->quality >= 9 && params->lgwin > lgblock) {
      lgblock = BR_MIN(18, params->lgwin);
    }
  } else {
    lgblock = BR_MIN(24, BR_MAX(16, lgblock));
  }
  return lgblock;
}

static int ComputeRbBits(const BrEncoderParams* params) {
  return 1 + BR_MAX(params->lgwin, params->lgblock);
}

static size_t MaxMetablockSize(const BrEncoderParams* params) {
  int bits = BR_MIN(ComputeRbBits(params), 24);
  return (size_t)1 << bits;
}

static void EncodeWindowBits(int lgwin, int large_window, uint16_t* last_bytes,
                             uint8_t* last_bytes_bits) {
  if (large_window) {
    *last_bytes = (uint16_t)(((lgwin & 0x3F) << 8) | 0x11);
    *last_bytes_bits = 14;
  } else {
    if (lgwin == 16) {
      *last_bytes = 0;
      *last_bytes_bits = 1;
    } else if (lgwin == 17) {
      *last_bytes = 1;
      *last_bytes_bits = 7;
    } else if (lgwin > 17) {
      *last_bytes = (uint16_t)(((lgwin - 17) << 1) | 0x01);
      *last_bytes_bits = 4;
    } else {
      *last_bytes = (uint16_t)(((lgwin - 8) << 4) | 0x01);
      *last_bytes_bits = 7;
    }
  }
}

static void ChooseDistanceParams(BrEncoderParams* params) {
  uint32_t distance_postfix_bits = 0;
  uint32_t num_direct_distance_codes = 0;
  if (params->quality >= 4) {
    uint32_t ndirect_msb;
    distance_postfix_bits = params->dist.distance_postfix_bits;
    num_direct_distance_codes = params->dist.num_direct_distance_codes;
    ndirect_msb = (num_direct_distance_codes >> distance_postfix_bits) & 0x0F;
    if (distance_postfix_bits > 3 || num_direct_distance_codes > 120 ||
        (ndirect_msb << distance_postfix_bits) != num_direct_distance_codes) {
      distance_postfix_bits = 0;
      num_direct_distance_codes = 0;
    }
  }
  BrInitDistanceParams(&params->dist, distance_postfix_bits,
                       num_direct_distance_codes, params->large_window);
}

static int EnsureInitialized(BrEncoder* s) {
  if (s->is_initialized_) return 1;
  s->last_bytes_bits_ = 0;
  s->last_bytes_ = 0;
  s->remaining_metadata_bytes_ = 0xFFFFFFFFu;
  SanitizeParams(&s->params);
  s->params.lgblock = ComputeLgBlock(&s->params);
  ChooseDistanceParams(&s->params);
  RingBufferSetup(ComputeRbBits(&s->params), s->params.lgblock,
                  &s->ringbuffer_);
  {
    int lgwin = s->params.lgwin;
    if (s->params.quality == 0 || s->params.quality == 1) {
      lgwin = BR_MAX(lgwin, 18);
    }
    EncodeWindowBits(lgwin, s->params.large_window, &s->last_bytes_,
                     &s->last_bytes_bits_);
  }
  if (s->params.quality == 0) {
    s->one_pass_arena_ = (BrOnePassArena*)calloc(1, sizeof(BrOnePassArena));
    BrInitCommandPrefixCodes(s->one_pass_arena_);
  } else if (s->params.quality == 1) {
    s->two_pass_arena_ = (BrTwoPassArena*)calloc(1, sizeof(BrTwoPassArena));
  }
  s->is_initialized_ = 1;
  return 1;
}

static uint8_t* GetBrotliStorage(BrEncoder* s, size_t size) {
  if (s->storage_size_ < size) {
    free(s->storage_);
    s->storage_ = (uint8_t*)malloc(size + 16);
    s->storage_size_ = size;
  }
  return s->storage_;
}

static size_t HashTableSize(size_t max_table_size, size_t input_size) {
  size_t htsize = 256;
  while (htsize < max_table_size && htsize < input_size) htsize <<= 1;
  return htsize;
}

static int* GetHashTable(BrEncoder* s, int quality, size_t input_size,
                         size_t* table_size) {
  const size_t max_table_size = quality == 0 ? (1 << 15) : (1 << 17);
  size_t htsize = HashTableSize(max_table_size, input_size);
  int* table;
  if (quality == 0) {
    if ((htsize & 0xAAAAA) == 0) htsize <<= 1;
  }
  if (htsize <= sizeof(s->small_table_) / sizeof(s->small_table_[0])) {
    table = s->small_table_;
  } else {
    if (htsize > s->large_table_size_) {
      s->large_table_size_ = htsize;
      free(s->large_table_);
      s->large_table_ = (int*)malloc(htsize * sizeof(int));
    }
    table = s->large_table_;
  }
  *table_size = htsize;
  memset(table, 0, htsize * sizeof(*table));
  return table;
}

static uint64_t UnprocessedInputSize(BrEncoder* s) {
  return s->input_pos_ - s->last_processed_pos_;
}

static size_t RemainingInputBlockSize(BrEncoder* s) {
  const uint64_t delta = UnprocessedInputSize(s);
  size_t block_size = (size_t)1 << s->params.lgblock;
  if (delta >= block_size) return 0;
  return block_size - (size_t)delta;
}

static uint32_t WrapPosition(uint64_t position) {
  uint32_t result = (uint32_t)position;
  uint64_t gb = position >> 30;
  if (gb > 2) {
    result = (result & ((1u << 30) - 1)) |
             ((uint32_t)((gb - 1) & 1) + 1) << 30;
  }
  return result;
}

static int UpdateLastProcessedPos(BrEncoder* s) {
  uint32_t wrapped_last_processed_pos = WrapPosition(s->last_processed_pos_);
  uint32_t wrapped_input_pos = WrapPosition(s->input_pos_);
  s->last_processed_pos_ = s->input_pos_;
  return wrapped_input_pos < wrapped_last_processed_pos;
}

static void CopyInputToRingBuffer(BrEncoder* s, const size_t input_size,
                                  const uint8_t* input_buffer) {
  BrRingBuffer* ringbuffer_ = &s->ringbuffer_;
  RingBufferWrite(input_buffer, input_size, ringbuffer_);
  s->input_pos_ += input_size;
  if (ringbuffer_->pos_ <= ringbuffer_->mask_) {
    memset(ringbuffer_->buffer_ + ringbuffer_->pos_, 0, 7);
  }
}

static void UpdateSizeHint(BrEncoder* s, size_t available_in) {
  if (s->params.size_hint == 0) {
    uint64_t delta = UnprocessedInputSize(s);
    uint64_t tail = available_in;
    uint32_t limit = 1u << 30;
    uint32_t total;
    if ((delta >= limit) || (tail >= limit) || ((delta + tail) >= limit)) {
      total = limit;
    } else {
      total = (uint32_t)(delta + tail);
    }
    s->params.size_hint = total;
  }
}

static int EncodeData(BrEncoder* s, const int is_last, const int force_flush,
                      size_t* out_size, uint8_t** output) {
  const uint64_t delta = UnprocessedInputSize(s);
  uint32_t bytes = (uint32_t)delta;
  uint32_t wrapped_last_processed_pos = WrapPosition(s->last_processed_pos_);
  uint8_t* data;
  uint32_t mask;
  int literal_context_mode;

  data = s->ringbuffer_.buffer_;
  mask = s->ringbuffer_.mask_;

  if (delta == 0) {
    if (!data) {
      if (is_last) {
        s->last_bytes_ |= (uint16_t)(3u << s->last_bytes_bits_);
        s->last_bytes_bits_ = (uint8_t)(s->last_bytes_bits_ + 2u);
        s->tiny_buf_[0] = (uint8_t)s->last_bytes_;
        s->tiny_buf_[1] = (uint8_t)(s->last_bytes_ >> 8);
        *output = s->tiny_buf_;
        *out_size = (s->last_bytes_bits_ + 7u) >> 3u;
        return 1;
      } else {
        *out_size = 0;
        return 1;
      }
    }
  }

  if (s->is_last_block_emitted_) return 0;
  if (is_last) s->is_last_block_emitted_ = 1;

  if (delta > ((size_t)1 << s->params.lgblock)) return 0;

  if (!s->pipe) s->pipe = BrPipelineCreate();

  {
    size_t newsize = s->num_commands_ + bytes / 2 + 1;
    if (newsize > s->cmd_alloc_size_) {
      Command* new_commands;
      newsize += (bytes / 4) + 16;
      s->cmd_alloc_size_ = newsize;
      new_commands = (Command*)malloc(sizeof(Command) * newsize);
      if (s->commands_) {
        memcpy(new_commands, s->commands_, sizeof(Command) * s->num_commands_);
        free(s->commands_);
      }
      s->commands_ = new_commands;
    }
  }

  BrPipelineInitOrStitch(s->pipe, data, mask, &s->params,
                         wrapped_last_processed_pos, bytes, is_last);

  literal_context_mode = BrChooseContextMode(
      &s->params, data, WrapPosition(s->last_flush_pos_), mask,
      (size_t)(s->input_pos_ - s->last_flush_pos_));

  if (s->num_commands_ && s->last_insert_len_ == 0) {
    BrExtendLastCommand(&s->params, s->commands_, s->num_commands_, data, mask,
                        s->last_processed_pos_, s->dist_cache_, &bytes,
                        &wrapped_last_processed_pos);
  }

  BrPipelineCreateBackwardReferences(
      s->pipe, bytes, wrapped_last_processed_pos, data, mask,
      literal_context_mode, &s->params, s->dist_cache_, &s->last_insert_len_,
      &s->commands_[s->num_commands_], &s->num_commands_, &s->num_literals_);

  {
    const size_t max_length = MaxMetablockSize(&s->params);
    const size_t max_literals = max_length / 8;
    const size_t max_commands = max_length / 8;
    const size_t processed_bytes = (size_t)(s->input_pos_ - s->last_flush_pos_);
    const int next_input_fits_metablock =
        processed_bytes + ((size_t)1 << s->params.lgblock) <= max_length;
    const int should_flush = s->params.quality < 4 &&
                             s->num_literals_ + s->num_commands_ >= 0x2FFF;
    if (!is_last && !force_flush && !should_flush &&
        next_input_fits_metablock && s->num_literals_ < max_literals &&
        s->num_commands_ < max_commands) {
      if (UpdateLastProcessedPos(s)) {
        BrPipelineHasherReset(s->pipe);
      }
      *out_size = 0;
      return 1;
    }
  }

  if (s->last_insert_len_ > 0) {
    InitInsertCommand(&s->commands_[s->num_commands_++], s->last_insert_len_);
    s->num_literals_ += s->last_insert_len_;
    s->last_insert_len_ = 0;
  }

  if (!is_last && s->input_pos_ == s->last_flush_pos_) {
    *out_size = 0;
    return 1;
  }
  {
    const uint32_t metablock_size =
        (uint32_t)(s->input_pos_ - s->last_flush_pos_);
    uint8_t* storage = GetBrotliStorage(s, 2 * metablock_size + 503);
    size_t storage_ix = s->last_bytes_bits_;
    storage[0] = (uint8_t)s->last_bytes_;
    storage[1] = (uint8_t)(s->last_bytes_ >> 8);
    BrWriteMetaBlockInternal(data, mask, s->last_flush_pos_, metablock_size,
                             is_last, literal_context_mode, &s->params,
                             s->prev_byte_, s->prev_byte2_, s->num_literals_,
                             s->num_commands_, s->commands_,
                             s->saved_dist_cache_, s->dist_cache_, &storage_ix,
                             storage);
    s->last_bytes_ = (uint16_t)(storage[storage_ix >> 3]);
    s->last_bytes_bits_ = storage_ix & 7u;
    s->last_flush_pos_ = s->input_pos_;
    if (UpdateLastProcessedPos(s)) {
      BrPipelineHasherReset(s->pipe);
    }
    if (s->last_flush_pos_ > 0) {
      s->prev_byte_ = data[((uint32_t)s->last_flush_pos_ - 1) & mask];
    }
    if (s->last_flush_pos_ > 1) {
      s->prev_byte2_ = data[(uint32_t)(s->last_flush_pos_ - 2) & mask];
    }
    s->num_commands_ = 0;
    s->num_literals_ = 0;
    memcpy(s->saved_dist_cache_, s->dist_cache_, sizeof(s->saved_dist_cache_));
    *output = storage;
    *out_size = storage_ix >> 3;
    return 1;
  }
}

static size_t WriteMetadataHeader(BrEncoder* s, const size_t block_size,
                                  uint8_t* header) {
  size_t storage_ix;
  storage_ix = s->last_bytes_bits_;
  header[0] = (uint8_t)s->last_bytes_;
  header[1] = (uint8_t)(s->last_bytes_ >> 8);
  s->last_bytes_ = 0;
  s->last_bytes_bits_ = 0;
  WriteBits(1, 0, &storage_ix, header);
  WriteBits(2, 3, &storage_ix, header);
  WriteBits(1, 0, &storage_ix, header);
  if (block_size == 0) {
    WriteBits(2, 0, &storage_ix, header);
  } else {
    uint32_t nbits = (block_size == 1)
                         ? 1
                         : (Log2FloorNonZero((uint32_t)block_size - 1) + 1);
    uint32_t nbytes = (nbits + 7) / 8;
    WriteBits(2, nbytes, &storage_ix, header);
    WriteBits(8 * nbytes, block_size - 1, &storage_ix, header);
  }
  return (storage_ix + 7u) >> 3;
}

static void InjectBytePaddingBlock(BrEncoder* s) {
  uint32_t seal = s->last_bytes_;
  size_t seal_bits = s->last_bytes_bits_;
  uint8_t* destination;
  s->last_bytes_ = 0;
  s->last_bytes_bits_ = 0;
  seal |= 0x6u << seal_bits;
  seal_bits += 6;
  if (s->next_out_) {
    destination = s->next_out_ + s->available_out_;
  } else {
    destination = s->tiny_buf_;
    s->next_out_ = destination;
  }
  destination[0] = (uint8_t)seal;
  if (seal_bits > 8) destination[1] = (uint8_t)(seal >> 8);
  if (seal_bits > 16) destination[2] = (uint8_t)(seal >> 16);
  s->available_out_ += (seal_bits + 7) >> 3;
}

static int InjectFlushOrPushOutput(BrEncoder* s, size_t* available_out,
                                   uint8_t** next_out) {
  if (s->stream_state_ == STREAM_FLUSH_REQUESTED && s->last_bytes_bits_ != 0) {
    InjectBytePaddingBlock(s);
    return 1;
  }
  if (s->available_out_ != 0 && *available_out != 0) {
    size_t copy_output_size = BR_MIN(s->available_out_, *available_out);
    memcpy(*next_out, s->next_out_, copy_output_size);
    *next_out += copy_output_size;
    *available_out -= copy_output_size;
    s->next_out_ += copy_output_size;
    s->available_out_ -= copy_output_size;
    s->total_out_ += copy_output_size;
    return 1;
  }
  return 0;
}

static void CheckFlushComplete(BrEncoder* s) {
  if (s->stream_state_ == STREAM_FLUSH_REQUESTED && s->available_out_ == 0) {
    s->stream_state_ = STREAM_PROCESSING;
    s->next_out_ = 0;
  }
}

static int CompressStreamFast(BrEncoder* s, int op, size_t* available_in,
                              const uint8_t** next_in, size_t* available_out,
                              uint8_t** next_out) {
  const size_t block_size_limit = (size_t)1 << s->params.lgwin;
  const size_t buf_size = BR_MIN((size_t)BR_TWO_PASS_BLOCK_SIZE,
                                 BR_MIN(*available_in, block_size_limit));
  uint32_t* tmp_command_buf = NULL;
  uint32_t* command_buf = NULL;
  uint8_t* tmp_literal_buf = NULL;
  uint8_t* literal_buf = NULL;
  if (s->params.quality == 1) {
    if (!s->command_buf_ && buf_size == BR_TWO_PASS_BLOCK_SIZE) {
      s->command_buf_ =
          (uint32_t*)malloc(sizeof(uint32_t) * BR_TWO_PASS_BLOCK_SIZE);
      s->literal_buf_ = (uint8_t*)malloc(BR_TWO_PASS_BLOCK_SIZE);
    }
    if (s->command_buf_) {
      command_buf = s->command_buf_;
      literal_buf = s->literal_buf_;
    } else {
      tmp_command_buf = (uint32_t*)malloc(sizeof(uint32_t) * (buf_size + 1));
      tmp_literal_buf = (uint8_t*)malloc(buf_size + 1);
      command_buf = tmp_command_buf;
      literal_buf = tmp_literal_buf;
    }
  }
  for (;;) {
    if (InjectFlushOrPushOutput(s, available_out, next_out)) continue;
    if (s->available_out_ == 0 && s->stream_state_ == STREAM_PROCESSING &&
        (*available_in != 0 || op != BRE_OP_PROCESS)) {
      size_t block_size = BR_MIN(block_size_limit, *available_in);
      int is_last = (*available_in == block_size) && (op == BRE_OP_FINISH);
      int force_flush = (*available_in == block_size) && (op == BRE_OP_FLUSH);
      size_t max_out_size = 2 * block_size + 503;
      int inplace = 1;
      uint8_t* storage = NULL;
      size_t storage_ix = s->last_bytes_bits_;
      size_t table_size;
      int* table;
      if (force_flush && block_size == 0) {
        s->stream_state_ = STREAM_FLUSH_REQUESTED;
        continue;
      }
      if (max_out_size + 16 <= *available_out) {
        storage = *next_out;
      } else {
        inplace = 0;
        storage = GetBrotliStorage(s, max_out_size);
      }
      storage[0] = (uint8_t)s->last_bytes_;
      storage[1] = (uint8_t)(s->last_bytes_ >> 8);
      table = GetHashTable(s, s->params.quality, block_size, &table_size);
      if (s->params.quality == 0) {
        BrCompressFragmentFast(s->one_pass_arena_, *next_in, block_size,
                               is_last, table, table_size, &storage_ix,
                               storage);
      } else {
        BrCompressFragmentTwoPass(s->two_pass_arena_, *next_in, block_size,
                                  is_last, command_buf, literal_buf, table,
                                  table_size, &storage_ix, storage);
      }
      if (block_size != 0) {
        *next_in += block_size;
        *available_in -= block_size;
      }
      if (inplace) {
        size_t out_bytes = storage_ix >> 3;
        *next_out += out_bytes;
        *available_out -= out_bytes;
        s->total_out_ += out_bytes;
      } else {
        size_t out_bytes = storage_ix >> 3;
        s->next_out_ = storage;
        s->available_out_ = out_bytes;
      }
      s->last_bytes_ = (uint16_t)(storage[storage_ix >> 3]);
      s->last_bytes_bits_ = storage_ix & 7u;
      if (force_flush) s->stream_state_ = STREAM_FLUSH_REQUESTED;
      if (is_last) s->stream_state_ = STREAM_FINISHED;
      continue;
    }
    break;
  }
  free(tmp_command_buf);
  free(tmp_literal_buf);
  CheckFlushComplete(s);
  return 1;
}

static int ProcessMetadata(BrEncoder* s, size_t* available_in,
                           const uint8_t** next_in, size_t* available_out,
                           uint8_t** next_out) {
  if (*available_in > (1u << 24)) return 0;
  if (s->stream_state_ == STREAM_PROCESSING) {
    s->remaining_metadata_bytes_ = (uint32_t)*available_in;
    s->stream_state_ = STREAM_METADATA_HEAD;
  }
  if (s->stream_state_ != STREAM_METADATA_HEAD &&
      s->stream_state_ != STREAM_METADATA_BODY) {
    return 0;
  }
  for (;;) {
    if (InjectFlushOrPushOutput(s, available_out, next_out)) continue;
    if (s->available_out_ != 0) break;
    if (s->input_pos_ != s->last_flush_pos_) {
      int result =
          EncodeData(s, 0, 1, &s->available_out_, &s->next_out_);
      if (!result) return 0;
      continue;
    }
    if (s->stream_state_ == STREAM_METADATA_HEAD) {
      s->next_out_ = s->tiny_buf_;
      s->available_out_ =
          WriteMetadataHeader(s, s->remaining_metadata_bytes_, s->next_out_);
      s->stream_state_ = STREAM_METADATA_BODY;
      continue;
    } else {
      if (s->remaining_metadata_bytes_ == 0) {
        s->remaining_metadata_bytes_ = 0xFFFFFFFFu;
        s->stream_state_ = STREAM_PROCESSING;
        break;
      }
      if (*available_out) {
        uint32_t copy =
            (uint32_t)BR_MIN((size_t)s->remaining_metadata_bytes_, *available_out);
        memcpy(*next_out, *next_in, copy);
        *next_in += copy;
        *available_in -= copy;
        s->remaining_metadata_bytes_ -= copy;
        *next_out += copy;
        *available_out -= copy;
      } else {
        uint32_t copy = BR_MIN(s->remaining_metadata_bytes_, 16u);
        s->next_out_ = s->tiny_buf_;
        memcpy(s->next_out_, *next_in, copy);
        *next_in += copy;
        *available_in -= copy;
        s->remaining_metadata_bytes_ -= copy;
        s->available_out_ = copy;
      }
      continue;
    }
  }
  return 1;
}

int BrEncCompressStream(BrEncoder* s, int op, size_t* available_in,
                        const uint8_t** next_in, size_t* available_out,
                        uint8_t** next_out) {
  if (!EnsureInitialized(s)) return 0;
  if (s->remaining_metadata_bytes_ != 0xFFFFFFFFu) {
    if (*available_in != s->remaining_metadata_bytes_) return 0;
    if (op != BRE_OP_EMIT_METADATA) return 0;
  }
  if (op == BRE_OP_EMIT_METADATA) {
    UpdateSizeHint(s, 0);
    return ProcessMetadata(s, available_in, next_in, available_out, next_out);
  }
  if (s->stream_state_ == STREAM_METADATA_HEAD ||
      s->stream_state_ == STREAM_METADATA_BODY) {
    return 0;
  }
  if (s->stream_state_ != STREAM_PROCESSING && *available_in != 0) return 0;
  if (s->params.quality == 0 || s->params.quality == 1) {
    return CompressStreamFast(s, op, available_in, next_in, available_out,
                              next_out);
  }
  for (;;) {
    size_t remaining_block_size = RemainingInputBlockSize(s);
    if (remaining_block_size != 0 && *available_in != 0) {
      size_t copy_input_size = BR_MIN(remaining_block_size, *available_in);
      CopyInputToRingBuffer(s, copy_input_size, *next_in);
      *next_in += copy_input_size;
      *available_in -= copy_input_size;
      continue;
    }
    if (InjectFlushOrPushOutput(s, available_out, next_out)) continue;
    if (s->available_out_ == 0 && s->stream_state_ == STREAM_PROCESSING) {
      if (remaining_block_size == 0 || op != BRE_OP_PROCESS) {
        int is_last = (*available_in == 0) && op == BRE_OP_FINISH;
        int force_flush = (*available_in == 0) && op == BRE_OP_FLUSH;
        int result;
        UpdateSizeHint(s, *available_in);
        result = EncodeData(s, is_last, force_flush, &s->available_out_,
                            &s->next_out_);
        if (!result) return 0;
        if (force_flush) s->stream_state_ = STREAM_FLUSH_REQUESTED;
        if (is_last) s->stream_state_ = STREAM_FINISHED;
        continue;
      }
    }
    break;
  }
  CheckFlushComplete(s);
  return 1;
}

int BrEncIsFinished(BrEncoder* s) {
  return s->stream_state_ == STREAM_FINISHED && s->available_out_ == 0;
}

int BrEncHasMoreOutput(BrEncoder* s) { return s->available_out_ != 0; }
