/* Hashers (match finders) used by qualities 2..11. */
#ifndef BR_HASH_H_
#define BR_HASH_H_
#include <stddef.h>
#include <stdint.h>
#include "enc_common.h"
#include "encoder_internal.h"

extern const uint16_t kBrDictHashWords[32768];
extern const uint8_t kBrDictHashLengths[32768];

#define kHashMul32 0x1E35A7BDu
#define kHashMul64 0x1E35A7BD1E35A7BDull
#define kHashMul64Long 0x1FE35A7BD3579BD3ull

#define BR_SCORE_BASE (30 * 8 * sizeof(size_t))
#define BR_LITERAL_BYTE_SCORE 135
#define BR_DISTANCE_BIT_PENALTY 30

typedef struct {
  size_t len;
  size_t distance;
  size_t score;
  int len_code_delta;
} HasherSearchResult;

static inline size_t BackwardReferenceScore(size_t copy_length,
                                            size_t backward_reference_offset) {
  return BR_SCORE_BASE + BR_LITERAL_BYTE_SCORE * copy_length -
         BR_DISTANCE_BIT_PENALTY * Log2FloorNonZero(backward_reference_offset);
}

static inline size_t BackwardReferenceScoreUsingLastDistance(
    size_t copy_length) {
  return BR_LITERAL_BYTE_SCORE * copy_length + BR_SCORE_BASE + 15;
}

static inline size_t BackwardReferencePenaltyUsingLastDistance(
    size_t distance_short_code) {
  return (size_t)39 + ((0x1CA10 >> (distance_short_code & 0xE)) & 0xE);
}

static inline uint32_t Hash14(const uint8_t* data) {
  uint32_t h = Load32(data) * kHashMul32;
  return h >> (32 - 14);
}

static inline void PrepareDistanceCache(int* distance_cache,
                                        const int num_distances) {
  if (num_distances > 4) {
    int last_distance = distance_cache[0];
    distance_cache[4] = last_distance - 1;
    distance_cache[5] = last_distance + 1;
    distance_cache[6] = last_distance - 2;
    distance_cache[7] = last_distance + 2;
    distance_cache[8] = last_distance - 3;
    distance_cache[9] = last_distance + 3;
    if (num_distances > 10) {
      int next_last_distance = distance_cache[1];
      distance_cache[10] = next_last_distance - 1;
      distance_cache[11] = next_last_distance + 1;
      distance_cache[12] = next_last_distance - 2;
      distance_cache[13] = next_last_distance + 2;
      distance_cache[14] = next_last_distance - 3;
      distance_cache[15] = next_last_distance + 3;
    }
  }
}

/* cutoff transforms: 0, 12, 27, 23, 42, 63, 56, 48, 59, 64 */
static inline size_t CutoffTransformId(size_t cut) {
  static const uint8_t kIds[10] = {0, 12, 27, 23, 42, 63, 56, 48, 59, 64};
  return kIds[cut];
}

typedef struct BrHasher BrHasher;

typedef struct {
  size_t dict_num_lookups;
  size_t dict_num_matches;
} HasherCommon;

static inline int TestStaticDictionaryItem(size_t len, size_t word_idx,
                                           const uint8_t* data,
                                           size_t max_length,
                                           size_t max_backward,
                                           size_t max_distance,
                                           HasherSearchResult* out) {
  size_t offset;
  size_t matchlen;
  size_t backward;
  size_t score;
  offset = kBrDictOffsets[len] + len * word_idx;
  if (len > max_length) return 0;
  matchlen = FindMatchLengthWithLimit(data, &kBrDictData[offset], len);
  if (matchlen + 10 <= len || matchlen == 0) return 0;
  {
    size_t cut = len - matchlen;
    size_t transform_id = CutoffTransformId(cut);
    backward = max_backward + 1 + word_idx +
               (transform_id << kBrDictSizeBits[len]);
  }
  if (backward > max_distance) return 0;
  score = BackwardReferenceScore(matchlen, backward);
  if (score < out->score) return 0;
  out->len = matchlen;
  out->len_code_delta = (int)len - (int)matchlen;
  out->distance = backward;
  out->score = score;
  return 1;
}

static inline void SearchInStaticDictionary(HasherCommon* common,
                                            const uint8_t* data,
                                            size_t max_length,
                                            size_t max_backward,
                                            size_t max_distance,
                                            HasherSearchResult* out,
                                            int shallow) {
  size_t key;
  size_t i;
  if (common->dict_num_matches < (common->dict_num_lookups >> 7)) return;
  key = Hash14(data) << 1;
  for (i = 0; i < (shallow ? 1u : 2u); ++i, ++key) {
    common->dict_num_lookups++;
    if (kBrDictHashLengths[key] != 0) {
      int item_matches = TestStaticDictionaryItem(
          kBrDictHashLengths[key], kBrDictHashWords[key], data, max_length,
          max_backward, max_distance, out);
      if (item_matches) common->dict_num_matches++;
    }
  }
}

#endif
EOF
echo ok"}

