/* Match finders for qualities 2..11. */
#include "hasher.h"

#include <stdlib.h>
#include <string.h>

void BrHasherInit(BrHasher* h) { memset(h, 0, sizeof(*h)); }

void BrHasherFree(BrHasher* h) {
  free(h->buckets);
  free(h->num);
  free(h->fc_addr);
  free(h->fc_head);
  free(h->fc_tiny_hash);
  free(h->fc_banks);
  free(h->forest);
  memset(h, 0, sizeof(*h));
}

static void ChooseHasher(const BrEncoderParams* params,
                         BrHasherParams* hparams) {
  if (params->quality > 9) {
    hparams->type = 10;
  } else if (params->quality == 4 && params->size_hint >= (1 << 20)) {
    hparams->type = 54;
  } else if (params->quality < 5) {
    hparams->type = params->quality;
  } else if (params->lgwin <= 16) {
    hparams->type = params->quality < 7 ? 40 : params->quality < 9 ? 41 : 42;
  } else if (params->size_hint >= (1 << 20) && params->lgwin >= 19) {
    hparams->type = 6;
    hparams->block_bits = params->quality - 1;
    hparams->bucket_bits = 15;
    hparams->hash_len = 5;
    hparams->num_last_distances_to_check =
        params->quality < 7 ? 4 : params->quality < 9 ? 10 : 16;
  } else {
    hparams->type = 5;
    hparams->block_bits = params->quality - 1;
    hparams->bucket_bits = params->quality < 7 ? 14 : 15;
    hparams->num_last_distances_to_check =
        params->quality < 7 ? 4 : params->quality < 9 ? 10 : 16;
  }
  if (params->lgwin > 24) {
    if (hparams->type == 3) hparams->type = 35;
    if (hparams->type == 54) hparams->type = 55;
    if (hparams->type == 6) hparams->type = 65;
  }
}

/* ---------------- quickly hashers (H2, H3, H4, H54) ---------------- */

static inline uint32_t QHashBytes(const BrHasher* h, const uint8_t* data) {
  const uint64_t v =
      (Load64(data) << (64 - 8 * h->hash_len)) * kHashMul64;
  return (uint32_t)(v >> (64 - h->bucket_bits));
}

static void QPrepare(BrHasher* h, int one_shot, size_t input_size,
                     const uint8_t* data) {
  size_t bucket_size = (size_t)1 << h->bucket_bits;
  (void)one_shot;
  (void)input_size;
  (void)data;
  memset(h->buckets, 0, sizeof(uint32_t) * bucket_size);
}

static inline void QStore(BrHasher* h, const uint8_t* data, size_t mask,
                          size_t ix) {
  const uint32_t key = QHashBytes(h, &data[ix & mask]);
  if (h->sweep_bits == 0) {
    h->buckets[key] = (uint32_t)ix;
  } else {
    const uint32_t sweep_mask = ((1u << h->sweep_bits) - 1) << 3;
    const uint32_t off = (uint32_t)ix & sweep_mask;
    const uint32_t bucket_mask = (1u << h->bucket_bits) - 1;
    h->buckets[(key + off) & bucket_mask] = (uint32_t)ix;
  }
}

static void QFindLongestMatch(BrHasher* h, const uint8_t* data,
                              const size_t ring_buffer_mask,
                              const int* distance_cache, const size_t cur_ix,
                              const size_t max_length,
                              const size_t max_backward,
                              const size_t dictionary_distance,
                              const size_t max_distance,
                              HasherSearchResult* out) {
  uint32_t* buckets = h->buckets;
  const size_t best_len_in = out->len;
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  int compare_char = data[cur_ix_masked + best_len_in];
  size_t key = QHashBytes(h, &data[cur_ix_masked]);
  size_t key_out = 0;
  size_t min_score = out->score;
  size_t best_score = out->score;
  size_t best_len = best_len_in;
  size_t cached_backward = (size_t)distance_cache[0];
  size_t prev_ix = cur_ix - cached_backward;
  const size_t bucket_sweep = (size_t)1 << h->sweep_bits;
  const size_t bucket_mask = ((size_t)1 << h->bucket_bits) - 1;
  const size_t sweep_mask = (bucket_sweep - 1) << 3;
  out->len_code_delta = 0;
  if (prev_ix < cur_ix) {
    prev_ix &= (uint32_t)ring_buffer_mask;
    if (compare_char == data[prev_ix + best_len]) {
      const size_t len = FindMatchLengthWithLimit(
          &data[prev_ix], &data[cur_ix_masked], max_length);
      if (len >= 4) {
        const size_t score = BackwardReferenceScoreUsingLastDistance(len);
        if (best_score < score) {
          out->len = len;
          out->distance = cached_backward;
          out->score = score;
          if (bucket_sweep == 1) {
            buckets[key] = (uint32_t)cur_ix;
            return;
          } else {
            best_len = len;
            best_score = score;
            compare_char = data[cur_ix_masked + len];
          }
        }
      }
    }
  }
  if (bucket_sweep == 1) {
    size_t backward;
    size_t len;
    prev_ix = buckets[key];
    buckets[key] = (uint32_t)cur_ix;
    backward = cur_ix - prev_ix;
    prev_ix &= (uint32_t)ring_buffer_mask;
    if (compare_char != data[prev_ix + best_len_in]) return;
    if (backward == 0 || backward > max_backward) return;
    len = FindMatchLengthWithLimit(&data[prev_ix], &data[cur_ix_masked],
                                   max_length);
    if (len >= 4) {
      const size_t score = BackwardReferenceScore(len, backward);
      if (best_score < score) {
        out->len = len;
        out->distance = backward;
        out->score = score;
        return;
      }
    }
  } else {
    size_t keys[4];
    size_t i;
    for (i = 0; i < bucket_sweep; ++i) {
      keys[i] = (key + (i << 3)) & bucket_mask;
    }
    key_out = keys[(cur_ix & sweep_mask) >> 3];
    for (i = 0; i < bucket_sweep; ++i) {
      size_t len;
      size_t backward;
      prev_ix = buckets[keys[i]];
      backward = cur_ix - prev_ix;
      prev_ix &= (uint32_t)ring_buffer_mask;
      if (compare_char != data[prev_ix + best_len]) continue;
      if (backward == 0 || backward > max_backward) continue;
      len = FindMatchLengthWithLimit(&data[prev_ix], &data[cur_ix_masked],
                                     max_length);
      if (len >= 4) {
        const size_t score = BackwardReferenceScore(len, backward);
        if (best_score < score) {
          best_len = len;
          out->len = len;
          compare_char = data[cur_ix_masked + len];
          best_score = score;
          out->score = score;
          out->distance = backward;
        }
      }
    }
  }
  if (h->use_dictionary && min_score == out->score) {
    SearchInStaticDictionary(&h->common, &data[cur_ix_masked], max_length,
                             dictionary_distance, max_distance, out, 1);
  }
  if (bucket_sweep != 1) {
    buckets[key_out] = (uint32_t)cur_ix;
  }
}

/* ---------------- H5 / H6 ---------------- */

static inline uint32_t H5HashBytes(const BrHasher* h, const uint8_t* data) {
  uint32_t v = Load32(data) * kHashMul32;
  return (uint32_t)(v >> h->hash_shift);
}

static inline uint32_t H6HashBytes(const BrHasher* h, const uint8_t* data) {
  const uint64_t v = Load64(data) * h->hash_mul;
  return (uint32_t)(v >> (64 - 15));
}

static inline uint32_t H56Hash(const BrHasher* h, const uint8_t* data) {
  return h->params.type == 5 ? H5HashBytes(h, data) : H6HashBytes(h, data);
}

static inline void H56Store(BrHasher* h, const uint8_t* data, size_t mask,
                            size_t ix) {
  const uint32_t key = H56Hash(h, &data[ix & mask]);
  const size_t minor_ix = h->num[key] & h->block_mask;
  const size_t offset = minor_ix + ((size_t)key << h->block_bits);
  h->buckets[offset] = (uint32_t)ix;
  ++h->num[key];
}

static void H56FindLongestMatch(BrHasher* h, const uint8_t* data,
                                const size_t ring_buffer_mask,
                                const int* distance_cache,
                                const size_t cur_ix, const size_t max_length,
                                const size_t max_backward,
                                const size_t dictionary_distance,
                                const size_t max_distance,
                                HasherSearchResult* out) {
  uint16_t* num = h->num;
  uint32_t* buckets = h->buckets;
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  size_t min_score = out->score;
  size_t best_score = out->score;
  size_t best_len = out->len;
  size_t i;
  out->len = 0;
  out->len_code_delta = 0;
  for (i = 0; i < (size_t)h->num_last_distances_to_check; ++i) {
    const size_t backward = (size_t)distance_cache[i];
    size_t prev_ix = (size_t)(cur_ix - backward);
    if (prev_ix >= cur_ix) continue;
    if (backward > max_backward) continue;
    prev_ix &= ring_buffer_mask;
    if (cur_ix_masked + best_len > ring_buffer_mask ||
        prev_ix + best_len > ring_buffer_mask ||
        data[cur_ix_masked + best_len] != data[prev_ix + best_len]) {
      continue;
    }
    {
      const size_t len = FindMatchLengthWithLimit(
          &data[prev_ix], &data[cur_ix_masked], max_length);
      if (len >= 3 || (len == 2 && i < 2)) {
        size_t score = BackwardReferenceScoreUsingLastDistance(len);
        if (best_score < score) {
          if (i != 0) score -= BackwardReferencePenaltyUsingLastDistance(i);
          if (best_score < score) {
            best_score = score;
            best_len = len;
            out->len = best_len;
            out->distance = backward;
            out->score = best_score;
          }
        }
      }
    }
  }
  {
    const uint32_t key = H56Hash(h, &data[cur_ix_masked]);
    uint32_t* bucket = &buckets[(size_t)key << h->block_bits];
    const size_t down =
        (num[key] > h->block_size) ? (num[key] - h->block_size) : 0u;
    for (i = num[key]; i > down;) {
      size_t prev_ix = bucket[--i & h->block_mask];
      const size_t backward = cur_ix - prev_ix;
      if (backward > max_backward) break;
      prev_ix &= ring_buffer_mask;
      if (cur_ix_masked + best_len > ring_buffer_mask ||
          prev_ix + best_len > ring_buffer_mask ||
          data[cur_ix_masked + best_len] != data[prev_ix + best_len]) {
        continue;
      }
      {
        const size_t len = FindMatchLengthWithLimit(
            &data[prev_ix], &data[cur_ix_masked], max_length);
        if (len >= 4) {
          size_t score = BackwardReferenceScore(len, backward);
          if (best_score < score) {
            best_score = score;
            best_len = len;
            out->len = best_len;
            out->distance = backward;
            out->score = best_score;
          }
        }
      }
    }
    bucket[num[key] & h->block_mask] = (uint32_t)cur_ix;
    ++num[key];
  }
  if (min_score == out->score) {
    SearchInStaticDictionary(&h->common, &data[cur_ix_masked], max_length,
                             dictionary_distance, max_distance, out, 0);
  }
}

/* ---------------- forgetful chain H40 / H41 / H42 ---------------- */

static inline size_t FCHashBytes(const uint8_t* data) {
  const uint32_t v = Load32(data) * kHashMul32;
  return v >> (32 - 15);
}

static inline void FCStore(BrHasher* h, const uint8_t* data, size_t mask,
                           size_t ix) {
  const size_t key = FCHashBytes(&data[ix & mask]);
  const size_t bank = key & (size_t)(h->fc_num_banks - 1);
  const size_t bank_size = (size_t)1 << h->fc_bank_bits;
  const size_t idx = h->fc_free_slot_idx[bank]++ & (bank_size - 1);
  size_t delta = ix - h->fc_addr[key];
  FCSlot* slots = h->fc_banks + bank * bank_size;
  h->fc_tiny_hash[(uint16_t)ix] = (uint8_t)key;
  if (delta > 0xFFFF) delta = 0xFFFF;
  slots[idx].delta = (uint16_t)delta;
  slots[idx].next = h->fc_head[key];
  h->fc_addr[key] = (uint32_t)ix;
  h->fc_head[key] = (uint16_t)idx;
}

static void FCFindLongestMatch(BrHasher* h, const uint8_t* data,
                               const size_t ring_buffer_mask,
                               const int* distance_cache, const size_t cur_ix,
                               const size_t max_length,
                               const size_t max_backward,
                               const size_t dictionary_distance,
                               const size_t max_distance,
                               HasherSearchResult* out) {
  uint32_t* addr = h->fc_addr;
  uint16_t* head = h->fc_head;
  uint8_t* tiny_hashes = h->fc_tiny_hash;
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  size_t min_score = out->score;
  size_t best_score = out->score;
  size_t best_len = out->len;
  size_t i;
  const size_t key = FCHashBytes(&data[cur_ix_masked]);
  const uint8_t tiny_hash = (uint8_t)(key);
  const size_t bank_size = (size_t)1 << h->fc_bank_bits;
  out->len = 0;
  out->len_code_delta = 0;
  for (i = 0; i < (size_t)h->num_last_distances_to_check; ++i) {
    const size_t backward = (size_t)distance_cache[i];
    size_t prev_ix = (cur_ix - backward);
    if (i > 0 && tiny_hashes[(uint16_t)prev_ix] != tiny_hash) continue;
    if (prev_ix >= cur_ix || backward > max_backward) continue;
    prev_ix &= ring_buffer_mask;
    {
      const size_t len = FindMatchLengthWithLimit(
          &data[prev_ix], &data[cur_ix_masked], max_length);
      if (len >= 2) {
        size_t score = BackwardReferenceScoreUsingLastDistance(len);
        if (best_score < score) {
          if (i != 0) score -= BackwardReferencePenaltyUsingLastDistance(i);
          if (best_score < score) {
            best_score = score;
            best_len = len;
            out->len = best_len;
            out->distance = backward;
            out->score = best_score;
          }
        }
      }
    }
  }
  {
    const size_t bank = key & (size_t)(h->fc_num_banks - 1);
    FCSlot* slots = h->fc_banks + bank * bank_size;
    size_t backward = 0;
    size_t hops = h->fc_max_hops;
    size_t delta = cur_ix - addr[key];
    size_t slot = head[key];
    while (hops--) {
      size_t prev_ix;
      size_t last = slot;
      backward += delta;
      if (backward > max_backward) break;
      prev_ix = (cur_ix - backward) & ring_buffer_mask;
      slot = slots[last].next;
      delta = slots[last].delta;
      if (cur_ix_masked + best_len > ring_buffer_mask ||
          prev_ix + best_len > ring_buffer_mask ||
          data[cur_ix_masked + best_len] != data[prev_ix + best_len]) {
        continue;
      }
      {
        const size_t len = FindMatchLengthWithLimit(
            &data[prev_ix], &data[cur_ix_masked], max_length);
        if (len >= 4) {
          size_t score = BackwardReferenceScore(len, backward);
          if (best_score < score) {
            best_score = score;
            best_len = len;
            out->len = best_len;
            out->distance = backward;
            out->score = best_score;
          }
        }
      }
    }
    FCStore(h, data, ring_buffer_mask, cur_ix);
  }
  if (out->score == min_score) {
    SearchInStaticDictionary(&h->common, &data[cur_ix_masked], max_length,
                             dictionary_distance, max_distance, out, 0);
  }
}

/* ---------------- H10 (binary tree) ---------------- */
#define H10_BUCKET_BITS 17
#define MAX_TREE_SEARCH_DEPTH 64
#define MAX_TREE_COMP_LENGTH 128

static inline uint32_t H10HashBytes(const uint8_t* data) {
  uint32_t v = Load32(data) * kHashMul32;
  return v >> (32 - H10_BUCKET_BITS);
}

static inline size_t LeftChildIndex(const BrHasher* h, const size_t pos) {
  return 2 * (pos & h->window_mask);
}
static inline size_t RightChildIndex(const BrHasher* h, const size_t pos) {
  return 2 * (pos & h->window_mask) + 1;
}

static BackwardMatch* H10StoreAndFindMatches(
    BrHasher* h, const uint8_t* data, const size_t cur_ix,
    const size_t ring_buffer_mask, const size_t max_length,
    const size_t max_backward, size_t* const best_len,
    BackwardMatch* matches) {
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  const size_t max_comp_len = BR_MIN(max_length, (size_t)MAX_TREE_COMP_LENGTH);
  const int should_reroot_tree = max_length >= MAX_TREE_COMP_LENGTH;
  const uint32_t key = H10HashBytes(&data[cur_ix_masked]);
  uint32_t* buckets = h->buckets;
  uint32_t* forest = h->forest;
  size_t prev_ix = buckets[key];
  size_t node_left = LeftChildIndex(h, cur_ix);
  size_t node_right = RightChildIndex(h, cur_ix);
  size_t best_len_left = 0;
  size_t best_len_right = 0;
  size_t depth_remaining;
  if (should_reroot_tree) buckets[key] = (uint32_t)cur_ix;
  for (depth_remaining = MAX_TREE_SEARCH_DEPTH;; --depth_remaining) {
    const size_t backward = cur_ix - prev_ix;
    const size_t prev_ix_masked = prev_ix & ring_buffer_mask;
    if (backward == 0 || backward > max_backward || depth_remaining == 0) {
      if (should_reroot_tree) {
        forest[node_left] = h->invalid_pos;
        forest[node_right] = h->invalid_pos;
      }
      break;
    }
    {
      const size_t cur_len = BR_MIN(best_len_left, best_len_right);
      size_t len;
      len = cur_len + FindMatchLengthWithLimit(&data[cur_ix_masked + cur_len],
                                               &data[prev_ix_masked + cur_len],
                                               max_length - cur_len);
      if (matches && len > *best_len) {
        *best_len = len;
        InitBackwardMatch(matches++, backward, len);
      }
      if (len >= max_comp_len) {
        if (should_reroot_tree) {
          forest[node_left] = forest[LeftChildIndex(h, prev_ix)];
          forest[node_right] = forest[RightChildIndex(h, prev_ix)];
        }
        break;
      }
      if (data[cur_ix_masked + len] > data[prev_ix_masked + len]) {
        best_len_left = len;
        if (should_reroot_tree) forest[node_left] = (uint32_t)prev_ix;
        node_left = RightChildIndex(h, prev_ix);
        prev_ix = forest[node_left];
      } else {
        best_len_right = len;
        if (should_reroot_tree) forest[node_right] = (uint32_t)prev_ix;
        node_right = LeftChildIndex(h, prev_ix);
        prev_ix = forest[node_right];
      }
    }
  }
  return matches;
}

size_t BrH10FindAllMatches(BrHasher* h, const uint8_t* data,
                           size_t ring_buffer_mask, size_t cur_ix,
                           size_t max_length, size_t max_backward,
                           size_t dictionary_distance,
                           const BrEncoderParams* params,
                           BackwardMatch* matches) {
  BackwardMatch* const orig_matches = matches;
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  size_t best_len = 1;
  const size_t short_match_max_backward = params->quality != 11 ? 16 : 64;
  size_t stop = cur_ix - short_match_max_backward;
  uint32_t dict_matches[BR_MAX_STATIC_DICTIONARY_MATCH_LEN + 1];
  size_t i;
  if (cur_ix < short_match_max_backward) stop = 0;
  for (i = cur_ix - 1; i > stop && best_len <= 2; --i) {
    size_t prev_ix = i;
    const size_t backward = cur_ix - prev_ix;
    if (backward > max_backward) break;
    prev_ix &= ring_buffer_mask;
    if (data[cur_ix_masked] != data[prev_ix] ||
        data[cur_ix_masked + 1] != data[prev_ix + 1]) {
      continue;
    }
    {
      const size_t len = FindMatchLengthWithLimit(
          &data[prev_ix], &data[cur_ix_masked], max_length);
      if (len > best_len) {
        best_len = len;
        InitBackwardMatch(matches++, backward, len);
      }
    }
  }
  if (best_len < max_length) {
    matches = H10StoreAndFindMatches(h, data, cur_ix, ring_buffer_mask,
                                     max_length, max_backward, &best_len,
                                     matches);
  }
  for (i = 0; i <= BR_MAX_STATIC_DICTIONARY_MATCH_LEN; ++i) {
    dict_matches[i] = kInvalidMatch;
  }
  {
    size_t minlen = BR_MAX((size_t)4, best_len + 1);
    if (BrFindAllStaticDictionaryMatches(&data[cur_ix_masked], minlen,
                                         max_length, &dict_matches[0])) {
      size_t maxlen =
          BR_MIN((size_t)BR_MAX_STATIC_DICTIONARY_MATCH_LEN, max_length);
      size_t l;
      for (l = minlen; l <= maxlen; ++l) {
        uint32_t dict_id = dict_matches[l];
        if (dict_id < kInvalidMatch) {
          size_t distance = dictionary_distance + (dict_id >> 5) + 1;
          if (distance <= params->dist.max_distance) {
            InitDictionaryBackwardMatch(matches++, distance, l, dict_id & 31);
          }
        }
      }
    }
  }
  return (size_t)(matches - orig_matches);
}

void BrH10Store(BrHasher* h, const uint8_t* data, size_t mask, size_t ix) {
  const size_t max_backward = h->window_mask - 16 + 1;
  H10StoreAndFindMatches(h, data, ix, mask, MAX_TREE_COMP_LENGTH,
                         max_backward, NULL, NULL);
}

void BrH10StoreRange(BrHasher* h, const uint8_t* data, size_t mask,
                     size_t ix_start, size_t ix_end) {
  size_t i = ix_start;
  size_t j = ix_start;
  if (ix_start + 63 <= ix_end) i = ix_end - 63;
  if (ix_start + 512 <= i) {
    for (; j < i; j += 8) BrH10Store(h, data, mask, j);
  }
  for (; i < ix_end; ++i) BrH10Store(h, data, mask, i);
}

static void H10Stitch(BrHasher* h, size_t num_bytes, size_t position,
                      const uint8_t* ringbuffer, size_t ringbuffer_mask) {
  if (num_bytes >= 4 - 1 && position >= MAX_TREE_COMP_LENGTH) {
    const size_t i_start = position - MAX_TREE_COMP_LENGTH + 1;
    const size_t i_end = BR_MIN(position, i_start + num_bytes);
    size_t i;
    for (i = i_start; i < i_end; ++i) {
      const size_t max_backward =
          h->window_mask - BR_MAX((size_t)16 - 1, position - i);
      H10StoreAndFindMatches(h, ringbuffer, i, ringbuffer_mask,
                             MAX_TREE_COMP_LENGTH, max_backward, NULL, NULL);
    }
  }
}

/* ---------------- generic dispatch ---------------- */

static int IsQuickly(int type) {
  return type == 2 || type == 3 || type == 4 || type == 54 || type == 35 ||
         type == 55;
}
static int IsH56(int type) { return type == 5 || type == 6 || type == 65; }
static int IsFC(int type) { return type == 40 || type == 41 || type == 42; }

void BrHasherSetup(BrHasher* h, BrEncoderParams* params, const uint8_t* data,
                   size_t position, size_t input_size, int is_last) {
  int one_shot = (position == 0 && is_last);
  if (!h->is_setup) {
    int type;
    ChooseHasher(params, &params->hasher);
    h->params = params->hasher;
    h->common.dict_num_lookups = 0;
    h->common.dict_num_matches = 0;
    type = h->params.type;
    if (IsQuickly(type)) {
      int t = type == 35 ? 3 : type == 55 ? 54 : type;
      switch (t) {
        case 2: h->bucket_bits = 16; h->sweep_bits = 0; h->hash_len = 5; h->use_dictionary = 1; break;
        case 3: h->bucket_bits = 16; h->sweep_bits = 1; h->hash_len = 5; h->use_dictionary = 0; break;
        case 4: h->bucket_bits = 17; h->sweep_bits = 2; h->hash_len = 5; h->use_dictionary = 1; break;
        default: h->bucket_bits = 20; h->sweep_bits = 2; h->hash_len = 7; h->use_dictionary = 0; break;
      }
      h->buckets = (uint32_t*)malloc(sizeof(uint32_t) << h->bucket_bits);
    } else if (IsH56(type)) {
      h->bucket_size = (size_t)1 << h->params.bucket_bits;
      h->block_size = (size_t)1 << h->params.block_bits;
      h->block_mask = (uint32_t)(h->block_size - 1);
      h->block_bits = h->params.block_bits;
      h->num_last_distances_to_check = h->params.num_last_distances_to_check;
      h->hash_shift = 32 - h->params.bucket_bits;
      h->hash_mul = kHashMul64 << (64 - 5 * 8);
      h->num = (uint16_t*)malloc(sizeof(uint16_t) * h->bucket_size);
      h->buckets =
          (uint32_t*)malloc(sizeof(uint32_t) * h->bucket_size * h->block_size);
    } else if (IsFC(type)) {
      h->num_last_distances_to_check = type == 40 ? 4 : type == 41 ? 10 : 16;
      h->fc_num_banks = type == 42 ? 512 : 1;
      h->fc_bank_bits = type == 42 ? 9 : 16;
      h->fc_max_hops = (size_t)(params->quality > 6 ? 7u : 8u)
                       << (params->quality - 4);
      h->fc_addr = (uint32_t*)malloc(sizeof(uint32_t) << 15);
      h->fc_head = (uint16_t*)malloc(sizeof(uint16_t) << 15);
      h->fc_tiny_hash = (uint8_t*)malloc(65536);
      h->fc_banks = (FCSlot*)malloc(sizeof(FCSlot) * (size_t)h->fc_num_banks
                                    << h->fc_bank_bits);
    } else if (type == 10) {
      size_t num_nodes = (size_t)1 << params->lgwin;
      if (one_shot && input_size < num_nodes) num_nodes = input_size;
      h->window_mask = ((size_t)1 << params->lgwin) - 1u;
      h->invalid_pos = (uint32_t)(0 - h->window_mask);
      h->buckets = (uint32_t*)malloc(sizeof(uint32_t) << H10_BUCKET_BITS);
      h->forest = (uint32_t*)malloc(2 * sizeof(uint32_t) * (num_nodes + 1));
      h->forest_nodes = num_nodes;
    }
    h->is_prepared = 0;
    h->is_setup = 1;
  }
  if (!h->is_prepared) {
    int type = h->params.type;
    if (IsQuickly(type)) {
      QPrepare(h, one_shot, input_size, data);
    } else if (IsH56(type)) {
      memset(h->num, 0, h->bucket_size * sizeof(h->num[0]));
    } else if (IsFC(type)) {
      memset(h->fc_addr, 0xCC, sizeof(uint32_t) << 15);
      memset(h->fc_head, 0, sizeof(uint16_t) << 15);
      memset(h->fc_tiny_hash, 0, 65536);
      memset(h->fc_free_slot_idx, 0, sizeof(h->fc_free_slot_idx));
    } else if (type == 10) {
      size_t i;
      for (i = 0; i < ((size_t)1 << H10_BUCKET_BITS); i++) {
        h->buckets[i] = h->invalid_pos;
      }
    }
    h->is_prepared = 1;
  }
}

size_t BrHasherHashTypeLength(const BrHasher* h) {
  int type = h->params.type;
  if (IsQuickly(type)) return 8;
  if (type == 6 || type == 65) return 8;
  return 4;
}

size_t BrHasherStoreLookahead(const BrHasher* h) {
  int type = h->params.type;
  if (IsQuickly(type)) return 8;
  if (type == 6 || type == 65) return 8;
  if (type == 10) return MAX_TREE_COMP_LENGTH;
  return 4;
}

void BrHasherPrepareDistanceCache(BrHasher* h, int* distance_cache) {
  int type = h->params.type;
  if (IsH56(type) || IsFC(type)) {
    PrepareDistanceCache(distance_cache, h->num_last_distances_to_check);
  }
}

void BrHasherStore(BrHasher* h, const uint8_t* data, size_t mask, size_t ix) {
  int type = h->params.type;
  if (IsQuickly(type)) {
    QStore(h, data, mask, ix);
  } else if (IsH56(type)) {
    H56Store(h, data, mask, ix);
  } else if (IsFC(type)) {
    FCStore(h, data, mask, ix);
  } else if (type == 10) {
    BrH10Store(h, data, mask, ix);
  }
}

void BrHasherStoreRange(BrHasher* h, const uint8_t* data, size_t mask,
                        size_t ix_start, size_t ix_end) {
  size_t i;
  if (h->params.type == 10) {
    BrH10StoreRange(h, data, mask, ix_start, ix_end);
    return;
  }
  for (i = ix_start; i < ix_end; ++i) BrHasherStore(h, data, mask, i);
}

void BrHasherStitch(BrHasher* h, size_t num_bytes, size_t position,
                    const uint8_t* ringbuffer, size_t mask) {
  int type = h->params.type;
  if (type == 10) {
    H10Stitch(h, num_bytes, position, ringbuffer, mask);
    return;
  }
  if (num_bytes >= BrHasherHashTypeLength(h) - 1 && position >= 3) {
    BrHasherStore(h, ringbuffer, mask, position - 3);
    BrHasherStore(h, ringbuffer, mask, position - 2);
    BrHasherStore(h, ringbuffer, mask, position - 1);
  }
}

void BrHasherFindLongestMatch(BrHasher* h, const uint8_t* data,
                              size_t ring_buffer_mask,
                              const int* distance_cache, size_t cur_ix,
                              size_t max_length, size_t max_backward,
                              size_t dictionary_distance, size_t max_distance,
                              HasherSearchResult* out) {
  int type = h->params.type;
  if (IsQuickly(type)) {
    QFindLongestMatch(h, data, ring_buffer_mask, distance_cache, cur_ix,
                      max_length, max_backward, dictionary_distance,
                      max_distance, out);
  } else if (IsH56(type)) {
    H56FindLongestMatch(h, data, ring_buffer_mask, distance_cache, cur_ix,
                        max_length, max_backward, dictionary_distance,
                        max_distance, out);
  } else {
    FCFindLongestMatch(h, data, ring_buffer_mask, distance_cache, cur_ix,
                       max_length, max_backward, dictionary_distance,
                       max_distance, out);
  }
}
