/* q2+ compression pipeline: backward references and metablock writing. */
#include "pipeline.h"

#include <stdlib.h>
#include <string.h>

#include "bit_stream.h"
#include "command.h"
#include "entropy.h"
#include "hasher.h"
#include "metablock.h"
#include "zopfli.h"

struct BrPipeline {
  BrHasher hasher;
};

BrPipeline* BrPipelineCreate(void) {
  BrPipeline* p = (BrPipeline*)calloc(1, sizeof(BrPipeline));
  BrHasherInit(&p->hasher);
  return p;
}

void BrPipelineDestroy(BrPipeline* p) {
  BrHasherFree(&p->hasher);
  free(p);
}

void BrPipelineHasherReset(BrPipeline* p) { p->hasher.is_prepared = 0; }

void BrPipelineInitOrStitch(BrPipeline* p, const uint8_t* data, size_t mask,
                            const BrEncoderParams* params, size_t position,
                            size_t input_size, int is_last) {
  BrHasherSetup(&p->hasher, (BrEncoderParams*)params, data, position,
                input_size, is_last);
  BrHasherStitch(&p->hasher, input_size, position, data, mask);
}

/* ---- UTF8 detection ---- */
static size_t ParseAsUTF8(int* symbol, const uint8_t* input, size_t size) {
  if ((input[0] & 0x80) == 0) {
    *symbol = input[0];
    if (*symbol > 0) return 1;
  }
  if (size > 1u && (input[0] & 0xE0) == 0xC0 && (input[1] & 0xC0) == 0x80) {
    *symbol = (((input[0] & 0x1F) << 6) | (input[1] & 0x3F));
    if (*symbol > 0x7F) return 2;
  }
  if (size > 2u && (input[0] & 0xF0) == 0xE0 && (input[1] & 0xC0) == 0x80 &&
      (input[2] & 0xC0) == 0x80) {
    *symbol = (((input[0] & 0x0F) << 12) | ((input[1] & 0x3F) << 6) |
               (input[2] & 0x3F));
    if (*symbol > 0x7FF) return 3;
  }
  if (size > 3u && (input[0] & 0xF8) == 0xF0 && (input[1] & 0xC0) == 0x80 &&
      (input[2] & 0xC0) == 0x80 && (input[3] & 0xC0) == 0x80) {
    *symbol = (((input[0] & 0x07) << 18) | ((input[1] & 0x3F) << 12) |
               ((input[2] & 0x3F) << 6) | (input[3] & 0x3F));
    if (*symbol > 0xFFFF && *symbol <= 0x10FFFF) return 4;
  }
  *symbol = 0x110000 | input[0];
  return 1;
}

int BrIsMostlyUTF8(const uint8_t* data, const size_t pos, const size_t mask,
                   const size_t length, const double min_fraction) {
  size_t size_utf8 = 0;
  size_t i = 0;
  while (i < length) {
    int symbol;
    size_t bytes_read =
        ParseAsUTF8(&symbol, &data[(pos + i) & mask], length - i);
    i += bytes_read;
    if (symbol < 0x110000) size_utf8 += bytes_read;
  }
  return (double)size_utf8 > min_fraction * (double)length;
}

int BrChooseContextMode(const BrEncoderParams* params, const uint8_t* data,
                        const size_t pos, const size_t mask,
                        const size_t length) {
  if (params->quality >= 10 && !BrIsMostlyUTF8(data, pos, mask, length, 0.75)) {
    return BR_CONTEXT_SIGNED;
  }
  return BR_CONTEXT_UTF8;
}

void BrExtendLastCommand(const BrEncoderParams* params, Command* commands,
                         size_t num_commands, const uint8_t* data,
                         uint32_t mask, uint64_t last_processed_pos_in,
                         const int* dist_cache, uint32_t* bytes,
                         uint32_t* wrapped_last_processed_pos) {
  Command* last_command = &commands[num_commands - 1];
  uint64_t max_backward_distance =
      (((uint64_t)1) << params->lgwin) - BR_WINDOW_GAP;
  uint64_t last_copy_len = last_command->copy_len_ & 0x1FFFFFF;
  uint64_t last_processed_pos = last_processed_pos_in - last_copy_len;
  uint64_t max_distance = last_processed_pos < max_backward_distance
                              ? last_processed_pos
                              : max_backward_distance;
  uint64_t cmd_dist = (uint64_t)dist_cache[0];
  uint32_t distance_code =
      CommandRestoreDistanceCode(last_command, &params->dist);
  size_t compound_dictionary_size = params->dict_len;
  if (distance_code < 16 || distance_code - (16 - 1) == cmd_dist) {
    if (cmd_dist <= max_distance) {
      while (*bytes != 0 && data[*wrapped_last_processed_pos & mask] ==
                                data[(*wrapped_last_processed_pos - cmd_dist) &
                                     mask]) {
        last_command->copy_len_++;
        (*bytes)--;
        (*wrapped_last_processed_pos)++;
      }
    } else {
      if ((cmd_dist - max_distance - 1) < compound_dictionary_size &&
          last_copy_len < cmd_dist - max_distance) {
        size_t address = compound_dictionary_size -
                         (size_t)(cmd_dist - max_distance) +
                         (size_t)last_copy_len;
        while (*bytes != 0 && address < compound_dictionary_size &&
               data[*wrapped_last_processed_pos & mask] ==
                   params->dict[address]) {
          last_command->copy_len_++;
          (*bytes)--;
          (*wrapped_last_processed_pos)++;
          address++;
        }
      }
    }
    GetLengthCode(last_command->insert_len_,
                  (size_t)((int)(last_command->copy_len_ & 0x1FFFFFF) +
                           (int)(last_command->copy_len_ >> 25)),
                  (last_command->dist_prefix_ & 0x3FF) == 0,
                  &last_command->cmd_prefix_);
  }
}

/* ---- greedy backward references (q2..q9) ---- */

static inline size_t ComputeDistanceCode(size_t distance, size_t max_distance,
                                         const int* dist_cache) {
  if (distance <= max_distance) {
    size_t distance_plus_3 = distance + 3;
    size_t offset0 = distance_plus_3 - (size_t)dist_cache[0];
    size_t offset1 = distance_plus_3 - (size_t)dist_cache[1];
    if (distance == (size_t)dist_cache[0]) {
      return 0;
    } else if (distance == (size_t)dist_cache[1]) {
      return 1;
    } else if (offset0 < 7) {
      return (0x9750468 >> (4 * offset0)) & 0xF;
    } else if (offset1 < 7) {
      return (0xFDB1ACE >> (4 * offset1)) & 0xF;
    } else if (distance == (size_t)dist_cache[2]) {
      return 2;
    } else if (distance == (size_t)dist_cache[3]) {
      return 3;
    }
  }
  return distance + 16 - 1;
}

static void CreateBackwardReferences(BrHasher* hasher, size_t num_bytes,
                                     size_t position,
                                     const uint8_t* ringbuffer,
                                     size_t ringbuffer_mask,
                                     const BrEncoderParams* params,
                                     int* dist_cache, size_t* last_insert_len,
                                     Command* commands, size_t* num_commands,
                                     size_t* num_literals) {
  const size_t max_backward_limit = ((size_t)1 << params->lgwin) - 16;
  const size_t position_offset = params->stream_offset;
  const Command* const orig_commands = commands;
  size_t insert_length = *last_insert_len;
  const size_t pos_end = position + num_bytes;
  const size_t store_lookahead = BrHasherStoreLookahead(hasher);
  const size_t hash_type_length = BrHasherHashTypeLength(hasher);
  const size_t store_end = num_bytes >= store_lookahead
                               ? position + num_bytes - store_lookahead + 1
                               : position;
  const size_t random_heuristics_window_size = params->quality < 9 ? 64 : 512;
  size_t apply_random_heuristics = position + random_heuristics_window_size;
  const size_t gap = params->dict_len;
  const size_t kMinScore = BR_SCORE_BASE + 100;

  BrHasherPrepareDistanceCache(hasher, dist_cache);

  while (position + hash_type_length < pos_end) {
    size_t max_length = pos_end - position;
    size_t max_distance = BR_MIN(position, max_backward_limit);
    size_t dictionary_start =
        BR_MIN(position + position_offset, max_backward_limit);
    HasherSearchResult sr;
    sr.len = 0;
    sr.len_code_delta = 0;
    sr.distance = 0;
    sr.score = kMinScore;
    BrHasherFindLongestMatch(hasher, ringbuffer, ringbuffer_mask, dist_cache,
                             position, max_length, max_distance,
                             dictionary_start + gap, params->dist.max_distance,
                             &sr);
    if (params->dict_len) {
      BrLookupCompoundDictionaryMatch(params, ringbuffer, ringbuffer_mask,
                                      dist_cache, position, max_length,
                                      dictionary_start,
                                      params->dist.max_distance, &sr);
    }
    if (sr.score > kMinScore) {
      int delayed_backward_references_in_row = 0;
      --max_length;
      for (;; --max_length) {
        const size_t cost_diff_lazy = 175;
        HasherSearchResult sr2;
        sr2.len = params->quality < 5 ? BR_MIN(sr.len - 1, max_length) : 0;
        sr2.len_code_delta = 0;
        sr2.distance = 0;
        sr2.score = kMinScore;
        max_distance = BR_MIN(position + 1, max_backward_limit);
        dictionary_start =
            BR_MIN(position + 1 + position_offset, max_backward_limit);
        BrHasherFindLongestMatch(hasher, ringbuffer, ringbuffer_mask,
                                 dist_cache, position + 1, max_length,
                                 max_distance, dictionary_start + gap,
                                 params->dist.max_distance, &sr2);
        if (params->dict_len) {
          BrLookupCompoundDictionaryMatch(params, ringbuffer, ringbuffer_mask,
                                          dist_cache, position + 1, max_length,
                                          dictionary_start,
                                          params->dist.max_distance, &sr2);
        }
        if (sr2.score >= sr.score + cost_diff_lazy) {
          ++position;
          ++insert_length;
          sr = sr2;
          if (++delayed_backward_references_in_row < 4 &&
              position + hash_type_length < pos_end) {
            continue;
          }
        }
        break;
      }
      apply_random_heuristics =
          position + 2 * sr.len + random_heuristics_window_size;
      dictionary_start = BR_MIN(position + position_offset, max_backward_limit);
      {
        size_t distance_code =
            ComputeDistanceCode(sr.distance, dictionary_start + gap, dist_cache);
        if ((sr.distance <= (dictionary_start + gap)) && distance_code > 0) {
          dist_cache[3] = dist_cache[2];
          dist_cache[2] = dist_cache[1];
          dist_cache[1] = dist_cache[0];
          dist_cache[0] = (int)sr.distance;
          BrHasherPrepareDistanceCache(hasher, dist_cache);
        }
        InitCommand(commands++, &params->dist, insert_length, sr.len,
                    sr.len_code_delta, distance_code);
      }
      *num_literals += insert_length;
      insert_length = 0;
      {
        size_t range_start = position + 2;
        size_t range_end = BR_MIN(position + sr.len, store_end);
        if (sr.distance < (sr.len >> 2)) {
          range_start = BR_MIN(
              range_end, BR_MAX(range_start, position + sr.len - (sr.distance << 2)));
        }
        BrHasherStoreRange(hasher, ringbuffer, ringbuffer_mask, range_start,
                           range_end);
      }
      position += sr.len;
    } else {
      ++insert_length;
      ++position;
      if (position > apply_random_heuristics) {
        if (position >
            apply_random_heuristics + 4 * random_heuristics_window_size) {
          const size_t kMargin = BR_MAX(store_lookahead - 1, (size_t)4);
          size_t pos_jump = BR_MIN(position + 16, pos_end - kMargin);
          for (; position < pos_jump; position += 4) {
            BrHasherStore(hasher, ringbuffer, ringbuffer_mask, position);
            insert_length += 4;
          }
        } else {
          const size_t kMargin = BR_MAX(store_lookahead - 1, (size_t)2);
          size_t pos_jump = BR_MIN(position + 8, pos_end - kMargin);
          for (; position < pos_jump; position += 2) {
            BrHasherStore(hasher, ringbuffer, ringbuffer_mask, position);
            insert_length += 2;
          }
        }
      }
    }
  }
  insert_length += pos_end - position;
  *last_insert_len = insert_length;
  *num_commands += (size_t)(commands - orig_commands);
}

void BrPipelineCreateBackwardReferences(
    BrPipeline* p, size_t num_bytes, size_t position, const uint8_t* ringbuffer,
    size_t ringbuffer_mask, int literal_context_mode,
    const BrEncoderParams* params, int* dist_cache, size_t* last_insert_len,
    Command* commands, size_t* num_commands, size_t* num_literals) {
  if (params->quality == 10 || params->quality == 11) {
    BrCreateZopfliBackwardReferences(&p->hasher, num_bytes, position,
                                     ringbuffer, ringbuffer_mask,
                                     literal_context_mode, params, dist_cache,
                                     last_insert_len, commands, num_commands,
                                     num_literals);
    return;
  }
  CreateBackwardReferences(&p->hasher, num_bytes, position, ringbuffer,
                           ringbuffer_mask, params, dist_cache,
                           last_insert_len, commands, num_commands,
                           num_literals);
}

/* ---- metablock writing ---- */

static int ShouldCompress(const uint8_t* data, const size_t mask,
                          const uint64_t last_flush_pos, const size_t bytes,
                          const size_t num_literals,
                          const size_t num_commands) {
  if (bytes <= 2) return 0;
  if (num_commands < (bytes >> 8) + 2) {
    if ((double)num_literals > 0.99 * (double)bytes) {
      uint32_t literal_histo[256] = {0};
      static const uint32_t kSampleRate = 13;
      static const double kMinEntropy = 7.92;
      const double bit_cost_threshold =
          (double)bytes * kMinEntropy / kSampleRate;
      size_t t = (bytes + kSampleRate - 1) / kSampleRate;
      uint32_t pos = (uint32_t)last_flush_pos;
      size_t i;
      for (i = 0; i < t; i++) {
        ++literal_histo[data[pos & mask]];
        pos += kSampleRate;
      }
      if (BrBitsEntropy(literal_histo, 256) > bit_cost_threshold) return 0;
    }
  }
  return 1;
}

static uint32_t WrapPosition(uint64_t position) {
  uint32_t result = (uint32_t)position;
  uint64_t gb = position >> 30;
  if (gb > 2) {
    result = (result & ((1u << 30) - 1)) |
             ((uint32_t)((gb - 1) & 1) + 1) << 30;
  }
  return result;
}

void BrWriteMetaBlockInternal(const uint8_t* data, const size_t mask,
                              const uint64_t last_flush_pos,
                              const size_t bytes, const int is_last,
                              int literal_context_mode,
                              const BrEncoderParams* params,
                              const uint8_t prev_byte,
                              const uint8_t prev_byte2,
                              const size_t num_literals,
                              const size_t num_commands, Command* commands,
                              const int* saved_dist_cache, int* dist_cache,
                              size_t* storage_ix, uint8_t* storage) {
  const uint32_t wrapped_last_flush_pos = WrapPosition(last_flush_pos);
  uint16_t last_bytes;
  uint8_t last_bytes_bits;
  BrEncoderParams block_params = *params;

  if (bytes == 0) {
    WriteBits(2, 3, storage_ix, storage);
    *storage_ix = (*storage_ix + 7u) & ~7u;
    return;
  }

  if (!ShouldCompress(data, mask, last_flush_pos, bytes, num_literals,
                      num_commands)) {
    memcpy(dist_cache, saved_dist_cache, 4 * sizeof(dist_cache[0]));
    BrStoreUncompressedMetaBlock(is_last, data, wrapped_last_flush_pos, mask,
                                 bytes, storage_ix, storage);
    return;
  }

  last_bytes = (uint16_t)((storage[1] << 8) | storage[0]);
  last_bytes_bits = (uint8_t)(*storage_ix);
  if (params->quality <= 2) {
    BrStoreMetaBlockFast(data, wrapped_last_flush_pos, bytes, mask, is_last,
                         params, commands, num_commands, storage_ix, storage);
  } else if (params->quality < 4) {
    BrStoreMetaBlockTrivial(data, wrapped_last_flush_pos, bytes, mask,
                            is_last, params, commands, num_commands,
                            storage_ix, storage);
  } else {
    BrBuildAndStoreMetaBlock(data, wrapped_last_flush_pos, mask, bytes,
                             is_last, literal_context_mode, &block_params,
                             prev_byte, prev_byte2, commands, num_commands,
                             storage_ix, storage);
  }
  if (bytes + 4 < (*storage_ix >> 3)) {
    memcpy(dist_cache, saved_dist_cache, 4 * sizeof(dist_cache[0]));
    storage[0] = (uint8_t)last_bytes;
    storage[1] = (uint8_t)(last_bytes >> 8);
    *storage_ix = last_bytes_bits;
    BrStoreUncompressedMetaBlock(is_last, data, wrapped_last_flush_pos, mask,
                                 bytes, storage_ix, storage);
  }
}
