static uint16_t kStaticCommandCodeBits[704];
static uint8_t kStaticDistanceCodeDepth[64];
static uint16_t kStaticDistanceCodeBits[64];
static int kStaticInit = 0;

static void InitStatic(void) {
  size_t i;
  if (kStaticInit) return;
  for (i = 0; i < 704; ++i) kStaticCommandCodeDepth[i] = i < 448 ? 9 : 11;
  BrConvertBitDepthsToSymbols(kStaticCommandCodeDepth, 704,
                              kStaticCommandCodeBits);
  for (i = 0; i < 64; ++i) kStaticDistanceCodeDepth[i] = 6;
  BrConvertBitDepthsToSymbols(kStaticDistanceCodeDepth, 64,
                              kStaticDistanceCodeBits);
  kStaticInit = 1;
}

void BrStoreCommandExtra(const Command* cmd, size_t* storage_ix,
                         uint8_t* storage) {
  uint32_t copylen_code = CommandCopyLenCode(cmd);
  uint16_t inscode = GetInsertLengthCode(cmd->insert_len_);
  uint16_t copycode = GetCopyLengthCode(copylen_code);
  uint32_t insnumextra = GetInsertExtra(inscode);
  uint64_t insextraval = cmd->insert_len_ - GetInsertBase(inscode);
  uint64_t copyextraval = copylen_code - GetCopyBase(copycode);
  uint64_t bits = (copyextraval << insnumextra) | insextraval;
  WriteBits(insnumextra + GetCopyExtra(copycode), bits, storage_ix, storage);
}

static void StoreDataWithHuffmanCodes(
    const uint8_t* input, size_t start_pos, size_t mask,
    const Command* commands, size_t n_commands, const uint8_t* lit_depth,
    const uint16_t* lit_bits, const uint8_t* cmd_depth,
    const uint16_t* cmd_bits, const uint8_t* dist_depth,
    const uint16_t* dist_bits, size_t* storage_ix, uint8_t* storage) {
  size_t pos = start_pos;
  size_t i;
  for (i = 0; i < n_commands; ++i) {
    const Command cmd = commands[i];
    const size_t cmd_code = cmd.cmd_prefix_;
    size_t j;
    WriteBits(cmd_depth[cmd_code], cmd_bits[cmd_code], storage_ix, storage);
    BrStoreCommandExtra(&cmd, storage_ix, storage);
    for (j = cmd.insert_len_; j != 0; --j) {
      const uint8_t literal = input[pos & mask];
      WriteBits(lit_depth[literal], lit_bits[literal], storage_ix, storage);
      ++pos;
    }
    pos += CommandCopyLen(&cmd);
    if (CommandCopyLen(&cmd) && cmd.cmd_prefix_ >= 128) {
      const size_t dist_code = cmd.dist_prefix_ & 0x3FF;
      const uint32_t distnumextra = cmd.dist_prefix_ >> 10;
      const uint32_t distextra = cmd.dist_extra_;
      WriteBits(dist_depth[dist_code], dist_bits[dist_code], storage_ix,
                storage);
      WriteBits(distnumextra, distextra, storage_ix, storage);
    }
  }
}

