                             size_t length, size_t mask, int is_last,
                             const BrEncoderParams* params,
                             const Command* commands, size_t n_commands,
                             size_t* storage_ix, uint8_t* storage) {
  uint32_t lit_histo[256] = {0};
  uint32_t cmd_histo[704] = {0};
  uint32_t dist_histo[MAX_SIMPLE_DISTANCE_ALPHABET_SIZE] = {0};
  size_t lt = 0, ct = 0, dt = 0;
  uint8_t lit_depth[256];
  uint16_t lit_bits[256];
  uint8_t cmd_depth[704];
  uint16_t cmd_bits[704];
  uint8_t dist_depth[MAX_SIMPLE_DISTANCE_ALPHABET_SIZE];
  uint16_t dist_bits[MAX_SIMPLE_DISTANCE_ALPHABET_SIZE];
  HuffmanTree tree[2 * 704 + 1];
  uint32_t num_distance_symbols = params->dist.alphabet_size_max;

  BrStoreCompressedMetaBlockHeader(is_last, length, storage_ix, storage);
