                  cmd_histo, &ct, dist_histo, &dt);
  WriteBits(13, 0, storage_ix, storage);
  BrBuildAndStoreHuffmanTree(lit_histo, 256, 256, tree, lit_depth, lit_bits,
                             storage_ix, storage);
  BrBuildAndStoreHuffmanTree(cmd_histo, 704, 704, tree, cmd_depth, cmd_bits,
                             storage_ix, storage);
  BrBuildAndStoreHuffmanTree(dist_histo, MAX_SIMPLE_DISTANCE_ALPHABET_SIZE,
                             num_distance_symbols, tree, dist_depth, dist_bits,
                             storage_ix, storage);
