static void EnsureSplit(BlockSplit* split, size_t n) {
  if (split->types_alloc_size < n) {
    split->types = (uint8_t*)realloc(split->types, n);
    split->types_alloc_size = n;
  }
  if (split->lengths_alloc_size < n) {
    split->lengths = (uint32_t*)realloc(split->lengths, n * sizeof(uint32_t));
    split->lengths_alloc_size = n;
  }
}

void BrInitMetaBlockSplit(MetaBlockSplit* mb) { memset(mb, 0, sizeof(*mb)); }

void BrDestroyMetaBlockSplit(MetaBlockSplit* mb) {
  free(mb->literal_split.types);
