/* Static dictionary match finder used by the Zopfli (q10/q11) search. */
#include <stdlib.h>
#include <string.h>

#include "enc_common.h"
#include "hasher.h"

typedef struct {
  uint8_t len;
  uint8_t transform;
  uint16_t idx;
} DictWord;

#define kDictNumBits 15
static const uint32_t kDictHashMul32 = 0x1E35A7BD;

static uint16_t* g_buckets = NULL;  /* 1 << 15, index into g_words (+1) */
static DictWord* g_words = NULL;
static size_t g_num_words = 0;

static inline uint32_t DictHash(const uint8_t* data) {
  uint32_t h = Load32(data) * kDictHashMul32;
  return h >> (32 - kDictNumBits);
}

static void BuildLut(void) {
  /* Collect entries per bucket, then lay them out contiguously. */
  size_t counts[1 << kDictNumBits];
  size_t total = 0;
  size_t* starts;
  size_t* fill;
  int pass;
  size_t L, i;
  memset(counts, 0, sizeof(counts));
  for (pass = 0; pass < 2; ++pass) {
    for (L = 4; L <= 24; ++L) {
      size_t n = (size_t)1 << kBrDictSizeBits[L];
      for (i = 0; i < n; ++i) {
        const uint8_t* w = &kBrDictData[kBrDictOffsets[L] + L * i];
        uint8_t tmp[24];
        int t;
        for (t = 0; t < 3; ++t) {
          uint32_t key;
          size_t k;
          if (t == 0) {
            memcpy(tmp, w, L);
          } else if (t == 1) {
            if (!(w[0] >= 'a' && w[0] <= 'z')) continue;
            memcpy(tmp, w, L);
            tmp[0] ^= 32;
          } else {
            int ascii = 1, lower = 0;
            for (k = 0; k < L; ++k) {
              if (w[k] >= 128) ascii = 0;
              if (w[k] >= 'a' && w[k] <= 'z') lower = 1;
            }
            if (!ascii || !lower) continue;
            for (k = 0; k < L; ++k) {
              tmp[k] = (w[k] >= 'a' && w[k] <= 'z') ? (uint8_t)(w[k] ^ 32) : w[k];
            }
          }
          key = DictHash(tmp);
          if (pass == 0) {
            counts[key]++;
            total++;
          } else {
            DictWord dw;
            dw.len = (uint8_t)L;
            dw.transform = (uint8_t)(t == 0 ? 0 : t == 1 ? 10 : 11);
            dw.idx = (uint16_t)i;
            g_words[fill[key]++] = dw;
          }
        }
      }
    }
    if (pass == 0) {
      size_t pos = 1;
      g_words = (DictWord*)malloc(sizeof(DictWord) * (total + 1));
      g_buckets = (uint16_t*)calloc((size_t)1 << kDictNumBits, sizeof(uint16_t));
      starts = (size_t*)malloc(sizeof(size_t) << kDictNumBits);
      fill = (size_t*)malloc(sizeof(size_t) << kDictNumBits);
      for (i = 0; i < ((size_t)1 << kDictNumBits); ++i) {
        starts[i] = pos;
        fill[i] = pos;
        if (counts[i]) {
          g_buckets[i] = (uint16_t)pos;
          pos += counts[i];
        }
      }
      g_num_words = total + 1;
    }
  }
  /* mark ends */
  for (i = 0; i < ((size_t)1 << kDictNumBits); ++i) {
    if (counts[i]) g_words[starts[i] + counts[i] - 1].len |= 0x80;
  }
  free(starts);
  free(fill);
}

static inline size_t DictMatchLength(const uint8_t* data, size_t id,
                                     size_t len, size_t maxlen) {
  const size_t offset = kBrDictOffsets[len] + len * id;
  return FindMatchLengthWithLimit(&kBrDictData[offset], data,
                                  BR_MIN(len, maxlen));
}

static inline int IsMatch(DictWord w, const uint8_t* data, size_t max_length) {
  if (w.len > max_length) {
    return 0;
  } else {
    const size_t offset = kBrDictOffsets[w.len] + (size_t)w.len * (size_t)w.idx;
    const uint8_t* dict = &kBrDictData[offset];
    if (w.transform == 0) {
      return FindMatchLengthWithLimit(dict, data, w.len) == w.len;
    } else if (w.transform == 10) {
      return dict[0] >= 'a' && dict[0] <= 'z' && (dict[0] ^ 32) == data[0] &&
             FindMatchLengthWithLimit(&dict[1], &data[1], w.len - 1u) ==
                 w.len - 1u;
    } else {
      size_t i;
      for (i = 0; i < w.len; ++i) {
        if (dict[i] >= 'a' && dict[i] <= 'z') {
          if ((dict[i] ^ 32) != data[i]) return 0;
        } else {
          if (dict[i] != data[i]) return 0;
        }
      }
      return 1;
    }
  }
}

