                    GetDistanceCost(model, dist_symbol & 0x3FF);
        max_match_len = BackwardMatchLength(&match);
        if (len < max_match_len &&
            (is_dictionary_match || max_match_len > max_zopfli_len)) {
          len = max_match_len;
        }
        for (; len <= max_match_len; ++len) {
          const size_t len_code =
              is_dictionary_match ? BackwardMatchLengthCode(&match) : len;
          const uint16_t copycode = GetCopyLengthCode(len_code);
          const uint16_t cmdcode = CombineLengthCodes(inscode, copycode, 0);
          const float cost = dist_cost + (float)GetCopyExtra(copycode) +
                             GetCommandCost(model, cmdcode);
          if (cost < nodes[pos + len].u.cost) {
            UpdateZopfliNode(nodes, pos, start, len, len_code, dist, 0, cost);
            result = BR_MAX(result, len);
          }
        }
      }
    }
  }
  return result;
}

static size_t ComputeShortestPathFromNodes(size_t num_bytes,
                                           ZopfliNode* nodes) {
  size_t index = num_bytes;
  size_t num_commands = 0;
  while ((nodes[index].dcode_insert_length & 0x7FFFFFF) == 0 &&
         nodes[index].length == 1) {
    --index;
  }
  nodes[index].u.next = 0xFFFFFFFFu;
  while (index != 0) {
    size_t len = ZopfliNodeCommandLength(&nodes[index]);
    index -= len;
    nodes[index].u.next = (uint32_t)len;
    num_commands++;
  }
  return num_commands;
}

static void ZopfliCreateCommands(const size_t num_bytes,
                                 const size_t block_start,
                                 const ZopfliNode* nodes, int* dist_cache,
                                 size_t* last_insert_len,
                                 const BrEncoderParams* params,
                                 Command* commands, size_t* num_literals) {
  const size_t stream_offset = params->stream_offset;
  const size_t max_backward_limit = ((size_t)1 << params->lgwin) - 16;
  size_t pos = 0;
  uint32_t offset = nodes[0].u.next;
  size_t i;
  size_t gap = params->dict_len;
  for (i = 0; offset != 0xFFFFFFFFu; i++) {
    const ZopfliNode* next = &nodes[pos + offset];
    size_t copy_length = ZopfliNodeCopyLength(next);
    size_t insert_length = next->dcode_insert_length & 0x7FFFFFF;
    pos += insert_length;
    offset = next->u.next;
    if (i == 0) {
      insert_length += *last_insert_len;
      *last_insert_len = 0;
    }
    {
      size_t distance = ZopfliNodeCopyDistance(next);
      size_t len_code = ZopfliNodeLengthCode(next);
      size_t dictionary_start =
          BR_MIN(block_start + pos + stream_offset, max_backward_limit);
      int is_dictionary = distance > dictionary_start + gap;
      size_t dist_code = ZopfliNodeDistanceCode(next);
      InitCommand(&commands[i], &params->dist, insert_length, copy_length,
                  (int)len_code - (int)copy_length, dist_code);
      if (!is_dictionary && dist_code > 0) {
        dist_cache[3] = dist_cache[2];
        dist_cache[2] = dist_cache[1];
        dist_cache[1] = dist_cache[0];
        dist_cache[0] = (int)distance;
      }
    }
    *num_literals += insert_length;
    pos += copy_length;
  }
  *last_insert_len += num_bytes - pos;
}

static size_t ZopfliIterate(size_t num_bytes, size_t position,
                            const uint8_t* ringbuffer, size_t ringbuffer_mask,
                            const BrEncoderParams* params, const size_t gap,
                            const int* dist_cache,
                            const ZopfliCostModel* model,
                            const uint32_t* num_matches,
                            const BackwardMatch* matches, ZopfliNode* nodes) {
  const size_t stream_offset = params->stream_offset;
  const size_t max_backward_limit = ((size_t)1 << params->lgwin) - 16;
  const size_t max_zopfli_len = params->quality <= 10 ? 150 : 325;
  StartPosQueue queue;
  size_t cur_match_pos = 0;
  size_t i;
  nodes[0].length = 0;
  nodes[0].u.cost = 0;
  InitStartPosQueue(&queue);
  for (i = 0; i + 3 < num_bytes; i++) {
    size_t skip = UpdateNodes(num_bytes, position, i, ringbuffer,
                              ringbuffer_mask, params, max_backward_limit,
                              dist_cache, num_matches[i],
                              &matches[cur_match_pos], model, &queue, nodes);
    if (skip < LONG_COPY_QUICK_STEP) skip = 0;
    cur_match_pos += num_matches[i];
    if (num_matches[i] == 1 &&
        BackwardMatchLength(&matches[cur_match_pos - 1]) > max_zopfli_len) {
      skip = BR_MAX(BackwardMatchLength(&matches[cur_match_pos - 1]), skip);
    }
    if (skip > 1) {
      skip--;
      while (skip) {
        i++;
        if (i + 3 >= num_bytes) break;
        EvaluateNode(position + stream_offset, i, max_backward_limit, gap,
                     dist_cache, model, &queue, nodes);
        cur_match_pos += num_matches[i];
        skip--;
      }
    }
  }
  return ComputeShortestPathFromNodes(num_bytes, nodes);
}

static size_t ZopfliComputeShortestPath(BrHasher* hasher, size_t num_bytes,
                                        size_t position,
                                        const uint8_t* ringbuffer,
                                        size_t ringbuffer_mask,
                                        const BrEncoderParams* params,
                                        const int* dist_cache,
                                        ZopfliNode* nodes) {
  const size_t stream_offset = params->stream_offset;
  const size_t max_backward_limit = ((size_t)1 << params->lgwin) - 16;
  const size_t max_zopfli_len = params->quality <= 10 ? 150 : 325;
  StartPosQueue queue;
  BackwardMatch* matches =
      (BackwardMatch*)malloc(sizeof(BackwardMatch) * 2 * (MAX_NUM_MATCHES_H10 + 64));
  const size_t store_end =
      num_bytes >= 128 ? position + num_bytes - 128 + 1 : position;
  size_t i;
  size_t gap = params->dict_len;
  size_t lz_matches_offset = gap ? (MAX_NUM_MATCHES_H10 + 128) : 0;
  ZopfliCostModel model;
  nodes[0].length = 0;
  nodes[0].u.cost = 0;
  InitZopfliCostModel(&model, &params->dist, num_bytes);
  ZopfliCostModelSetFromLiteralCosts(&model, position, ringbuffer,
                                     ringbuffer_mask);
  InitStartPosQueue(&queue);
  if (gap) {
    free(matches);
    matches = (BackwardMatch*)malloc(sizeof(BackwardMatch) *
                                     (lz_matches_offset + MAX_NUM_MATCHES_H10 + 128));
  }
  for (i = 0; i + 4 - 1 < num_bytes; i++) {
    const size_t pos = position + i;
    const size_t max_distance = BR_MIN(pos, max_backward_limit);
    const size_t dictionary_start =
        BR_MIN(pos + stream_offset, max_backward_limit);
    size_t skip;
    size_t num_matches;
    num_matches = BrH10FindAllMatches(hasher, ringbuffer, ringbuffer_mask, pos,
                                      num_bytes - i, max_distance,
                                      dictionary_start + gap, params,
                                      &matches[lz_matches_offset]);
    if (gap) {
      size_t cd_matches = BrLookupAllCompoundDictionaryMatches(
          params, ringbuffer, ringbuffer_mask, pos, 3, num_bytes - i,
          dictionary_start, params->dist.max_distance,
          &matches[lz_matches_offset - 64], 64);
      BrMergeMatches(matches, matches + lz_matches_offset - 64, cd_matches,
                     matches + lz_matches_offset, num_matches);
      num_matches += cd_matches;
    }
    if (num_matches > 0 &&
        BackwardMatchLength(&matches[num_matches - 1]) > max_zopfli_len) {
      matches[0] = matches[num_matches - 1];
      num_matches = 1;
    }
    skip = UpdateNodes(num_bytes, position, i, ringbuffer, ringbuffer_mask,
                       params, max_backward_limit, dist_cache, num_matches,
                       matches, &model, &queue, nodes);
    if (skip < LONG_COPY_QUICK_STEP) skip = 0;
    if (num_matches == 1 && BackwardMatchLength(&matches[0]) > max_zopfli_len) {
      skip = BR_MAX(BackwardMatchLength(&matches[0]), skip);
    }
    if (skip > 1) {
      BrH10StoreRange(hasher, ringbuffer, ringbuffer_mask, pos + 1,
                      BR_MIN(pos + skip, store_end));
      skip--;
      while (skip) {
        i++;
        if (i + 4 - 1 >= num_bytes) break;
        EvaluateNode(position + stream_offset, i, max_backward_limit, gap,
                     dist_cache, &model, &queue, nodes);
        skip--;
      }
    }
  }
  CleanupZopfliCostModel(&model);
  free(matches);
  return ComputeShortestPathFromNodes(num_bytes, nodes);
}

static void CreateZopfliBackwardReferences10(
    BrHasher* hasher, size_t num_bytes, size_t position,
    const uint8_t* ringbuffer, size_t ringbuffer_mask,
    const BrEncoderParams* params, int* dist_cache, size_t* last_insert_len,
    Command* commands, size_t* num_commands, size_t* num_literals) {
  ZopfliNode* nodes = (ZopfliNode*)malloc(sizeof(ZopfliNode) * (num_bytes + 1));
  InitZopfliNodes(nodes, num_bytes + 1);
  *num_commands += ZopfliComputeShortestPath(hasher, num_bytes, position,
                                             ringbuffer, ringbuffer_mask,
                                             params, dist_cache, nodes);
  ZopfliCreateCommands(num_bytes, position, nodes, dist_cache, last_insert_len,
                       params, commands, num_literals);
  free(nodes);
}

static void CreateHQZopfliBackwardReferences(
    BrHasher* hasher, size_t num_bytes, size_t position,
    const uint8_t* ringbuffer, size_t ringbuffer_mask,
    const BrEncoderParams* params, int* dist_cache, size_t* last_insert_len,
    Command* commands, size_t* num_commands, size_t* num_literals) {
  const size_t stream_offset = params->stream_offset;
  const size_t max_backward_limit = ((size_t)1 << params->lgwin) - 16;
  uint32_t* num_matches = (uint32_t*)malloc(sizeof(uint32_t) * (num_bytes + 1));
  size_t matches_size = 4 * num_bytes;
  const size_t store_end =
      num_bytes >= 128 ? position + num_bytes - 128 + 1 : position;
  size_t cur_match_pos = 0;
  size_t i;
  size_t orig_num_literals;
  size_t orig_last_insert_len;
  int orig_dist_cache[4];
  size_t orig_num_commands;
  ZopfliCostModel model;
  ZopfliNode* nodes;
  BackwardMatch* matches;
  size_t gap = params->dict_len;
  size_t shadow_matches = gap ? (MAX_NUM_MATCHES_H10 + 128) : 0;
  if (matches_size < 16) matches_size = 16;
  matches = (BackwardMatch*)malloc(sizeof(BackwardMatch) * matches_size);
  for (i = 0; i + 4 - 1 < num_bytes; ++i) {
    const size_t pos = position + i;
    size_t max_distance = BR_MIN(pos, max_backward_limit);
    size_t dictionary_start = BR_MIN(pos + stream_offset, max_backward_limit);
    size_t max_length = num_bytes - i;
    size_t num_found_matches;
    size_t cur_match_end;
    {
      size_t need = cur_match_pos + MAX_NUM_MATCHES_H10 + shadow_matches;
      if (need > matches_size) {
        size_t new_size = matches_size == 0 ? need : matches_size;
        while (new_size < need) new_size *= 2;
        matches = (BackwardMatch*)realloc(matches,
                                          sizeof(BackwardMatch) * new_size);
        matches_size = new_size;
      }
    }
    num_found_matches = BrH10FindAllMatches(
        hasher, ringbuffer, ringbuffer_mask, pos, max_length, max_distance,
        dictionary_start + gap, params,
        &matches[cur_match_pos + shadow_matches]);
    if (gap) {
      size_t cd_matches = BrLookupAllCompoundDictionaryMatches(
          params, ringbuffer, ringbuffer_mask, pos, 3, max_length,
          dictionary_start, params->dist.max_distance,
          &matches[cur_match_pos + shadow_matches - 64], 64);
      BrMergeMatches(&matches[cur_match_pos],
                     &matches[cur_match_pos + shadow_matches - 64], cd_matches,
                     &matches[cur_match_pos + shadow_matches],
                     num_found_matches);
      num_found_matches += cd_matches;
    }
    cur_match_end = cur_match_pos + num_found_matches;
    num_matches[i] = (uint32_t)num_found_matches;
    if (num_found_matches > 0) {
      const size_t match_len = BackwardMatchLength(&matches[cur_match_end - 1]);
      if (match_len > 325) {
        const size_t skip = match_len - 1;
        matches[cur_match_pos++] = matches[cur_match_end - 1];
        num_matches[i] = 1;
        BrH10StoreRange(hasher, ringbuffer, ringbuffer_mask, pos + 1,
                        BR_MIN(pos + match_len, store_end));
        memset(&num_matches[i + 1], 0, skip * sizeof(num_matches[0]));
        i += skip;
      } else {
        cur_match_pos = cur_match_end;
      }
    }
  }
  orig_num_literals = *num_literals;
  orig_last_insert_len = *last_insert_len;
  memcpy(orig_dist_cache, dist_cache, 4 * sizeof(dist_cache[0]));
  orig_num_commands = *num_commands;
  nodes = (ZopfliNode*)malloc(sizeof(ZopfliNode) * (num_bytes + 1));
  InitZopfliCostModel(&model, &params->dist, num_bytes);
  for (i = 0; i < 2; i++) {
    InitZopfliNodes(nodes, num_bytes + 1);
    if (i == 0) {
      ZopfliCostModelSetFromLiteralCosts(&model, position, ringbuffer,
                                         ringbuffer_mask);
    } else {
      ZopfliCostModelSetFromCommands(&model, position, ringbuffer,
                                     ringbuffer_mask, commands,
                                     *num_commands - orig_num_commands,
                                     orig_last_insert_len);
    }
    *num_commands = orig_num_commands;
    *num_literals = orig_num_literals;
    *last_insert_len = orig_last_insert_len;
    memcpy(dist_cache, orig_dist_cache, 4 * sizeof(dist_cache[0]));
    *num_commands += ZopfliIterate(num_bytes, position, ringbuffer,
                                   ringbuffer_mask, params, gap, dist_cache,
                                   &model, num_matches, matches, nodes);
    ZopfliCreateCommands(num_bytes, position, nodes, dist_cache,
                         last_insert_len, params, commands, num_literals);
  }
  CleanupZopfliCostModel(&model);
  free(nodes);
  free(matches);
  free(num_matches);
}

void BrCreateZopfliBackwardReferences(BrHasher* hasher, size_t num_bytes,
                                      size_t position,
                                      const uint8_t* ringbuffer,
                                      size_t ringbuffer_mask,
                                      int literal_context_mode,
                                      const BrEncoderParams* params,
                                      int* dist_cache, size_t* last_insert_len,
                                      Command* commands, size_t* num_commands,
                                      size_t* num_literals) {
  (void)literal_context_mode;
  if (params->quality == 10) {
    CreateZopfliBackwardReferences10(hasher, num_bytes, position, ringbuffer,
                                     ringbuffer_mask, params, dist_cache,
                                     last_insert_len, commands, num_commands,
                                     num_literals);
  } else {
    CreateHQZopfliBackwardReferences(hasher, num_bytes, position, ringbuffer,
                                     ringbuffer_mask, params, dist_cache,
                                     last_insert_len, commands, num_commands,
                                     num_literals);
  }
}
