static void RollPrepare(BrHasher* h, size_t input_size, const uint8_t* data) {
  size_t i;
  if (input_size < ROLL_CHUNKLEN) return;
  h->roll_state = 0;
  for (i = 0; i < ROLL_CHUNKLEN; i += h->roll_jump) {
    h->roll_state = h->roll_factor * h->roll_state + RollHashByte(data[i]);
  }
}

static void RollInitialize(BrHasher* h, uint32_t jump) {
  size_t i;
  h->rolling = 1;
  h->roll_jump = jump;
  h->roll_state = 0;
  h->roll_next_ix = 0;
  h->roll_factor = 69069;
  h->roll_factor_remove = 1;
  for (i = 0; i < ROLL_CHUNKLEN; i += jump) {
    h->roll_factor_remove *= h->roll_factor;
  }
  h->roll_table = (uint32_t*)malloc(sizeof(uint32_t) * ROLL_NUMBUCKETS);
  for (i = 0; i < ROLL_NUMBUCKETS; i++) h->roll_table[i] = ROLL_INVALID;
}

static void RollStitch(BrHasher* h, size_t num_bytes, size_t position,
                       const uint8_t* ringbuffer, size_t ring_buffer_mask) {
  size_t position_masked;
  size_t available = num_bytes;
  if ((position & (h->roll_jump - 1)) != 0) {
    size_t diff = h->roll_jump - (position & (h->roll_jump - 1));
    available = (diff > available) ? 0 : (available - diff);
    position += diff;
  }
  position_masked = position & ring_buffer_mask;
  if (available > ring_buffer_mask - position_masked) {
    available = ring_buffer_mask - position_masked;
  }
  RollPrepare(h, available, ringbuffer + (position & ring_buffer_mask));
  h->roll_next_ix = position;
}

static void RollFindLongestMatch(BrHasher* h, const uint8_t* data,
                                 const size_t ring_buffer_mask,
                                 const size_t cur_ix, const size_t max_length,
                                 const size_t max_backward,
                                 HasherSearchResult* out) {
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  size_t pos;
  if ((cur_ix & (h->roll_jump - 1)) != 0) return;
  if (max_length < ROLL_CHUNKLEN) return;
  for (pos = h->roll_next_ix; pos <= cur_ix; pos += h->roll_jump) {
    uint32_t code = h->roll_state & ROLL_MASK;
    uint8_t rem = data[pos & ring_buffer_mask];
    uint8_t add = data[(pos + ROLL_CHUNKLEN) & ring_buffer_mask];
    size_t found_ix = ROLL_INVALID;
    h->roll_state = (uint32_t)(h->roll_factor * h->roll_state +
                               RollHashByte(add) -
                               h->roll_factor_remove * RollHashByte(rem));
    if (code < ROLL_NUMBUCKETS) {
      found_ix = h->roll_table[code];
      h->roll_table[code] = (uint32_t)pos;
      if (pos == cur_ix && found_ix != ROLL_INVALID) {
        size_t backward = (uint32_t)(cur_ix - found_ix);
        if (backward <= max_backward) {
          const size_t found_ix_masked = found_ix & ring_buffer_mask;
          const size_t len = FindMatchLengthWithLimit(
              &data[found_ix_masked], &data[cur_ix_masked], max_length);
          if (len >= 4 && len > out->len) {
            size_t score = BackwardReferenceScore(len, backward);
            if (score > out->score) {
              out->len = len;
              out->distance = backward;
              out->score = score;
              out->len_code_delta = 0;
            }
          }
        }
      }
    }
  }
  h->roll_next_ix = cur_ix + h->roll_jump;
}

