    size_t cursor = slot_size[slot];
    if (count > slot_limit[slot]) count = slot_limit[slot];
    if (count == 0) {
      result->heads[i] = 0xFFFF;
      continue;
    }
    result->heads[i] = (uint16_t)cursor;
    cursor += result->slot_offsets[slot];
    slot_size[slot] += count;
    pos = bucket_heads[i];
    for (j = 0; j < count; j++) {
      result->items[cursor++] = pos;
      pos = next_bucket[pos];
    }
    result->items[cursor - 1] |= 0x80000000;
  }
  free(slot_size);
  free(slot_limit);
  free(num);
  free(bucket_heads);
  free(next_bucket);
  return result;
}

static PreparedDict* GetPrepared(const BrEncoderParams* params) {
  if (g_pd && g_pd_src == params->dict && g_pd_size == params->dict_len) {
    return g_pd;
  }
  {
    uint32_t bucket_bits = 17;
    uint32_t slot_bits = 7;
    uint32_t hash_bits = 40;
    uint16_t bucket_limit = 32;
    size_t volume = (size_t)16u << bucket_bits;
    while (volume < params->dict_len && bucket_bits < 22) {
      bucket_bits++;
      slot_bits++;
      volume <<= 1;
    }
    g_pd = CreateWithParams(params->dict, params->dict_len, bucket_bits,
                            slot_bits, hash_bits, bucket_limit);
    g_pd_src = params->dict;
    g_pd_size = params->dict_len;
  }
  return g_pd;
}

static void FindCompoundDictionaryMatch(const PreparedDict* self,
                                        const uint8_t* data,
                                        const size_t ring_buffer_mask,
                                        const int* distance_cache,
                                        const size_t cur_ix,
                                        const size_t max_length,
                                        const size_t distance_offset,
                                        const size_t max_distance,
                                        HasherSearchResult* out) {
  const uint32_t source_size = self->source_size;
  const size_t boundary = distance_offset - source_size;
  const uint32_t hash_shift = 64u - self->bucket_bits;
  const uint32_t slot_mask = (~((uint32_t)0U)) >> (32 - self->slot_bits);
  const uint64_t hash_mask = (~((uint64_t)0U)) >> (64 - self->hash_bits);
  const uint8_t* source = self->source;
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  size_t best_score = out->score;
  size_t best_len = out->len;
  size_t i;
  const uint64_t h = (Load64(&data[cur_ix_masked]) & hash_mask) * kHashMul64Long;
  const uint32_t key = (uint32_t)(h >> hash_shift);
  const uint32_t slot = key & slot_mask;
  const uint32_t head = self->heads[key];
  const uint32_t* chain = &self->items[self->slot_offsets[slot] + head];
  uint32_t item = (head == 0xFFFF) ? 1 : 0;
  for (i = 0; i < 4; ++i) {
    const size_t distance = (size_t)distance_cache[i];
    size_t offset;
    size_t limit;
    size_t len;
    if (distance <= boundary || distance > distance_offset) continue;
    offset = distance_offset - distance;
    limit = source_size - offset;
    limit = limit > max_length ? max_length : limit;
    len = FindMatchLengthWithLimit(&source[offset], &data[cur_ix_masked], limit);
    if (len >= 2) {
      size_t score = BackwardReferenceScoreUsingLastDistance(len);
      if (best_score < score) {
        if (i != 0) score -= BackwardReferencePenaltyUsingLastDistance(i);
        if (best_score < score) {
          best_score = score;
          if (len > best_len) best_len = len;
          out->len = len;
          out->len_code_delta = 0;
          out->distance = distance;
          out->score = best_score;
        }
      }
    }
  }
  while (item == 0) {
    size_t offset;
    size_t distance;
    size_t limit;
    item = *chain;
    chain++;
    offset = item & 0x7FFFFFFF;
    item &= 0x80000000;
    distance = distance_offset - offset;
    limit = source_size - offset;
    limit = (limit > max_length) ? max_length : limit;
    if (distance > max_distance) continue;
    if (cur_ix_masked + best_len > ring_buffer_mask || best_len >= limit ||
        data[cur_ix_masked + best_len] != source[offset + best_len]) {
      continue;
    }
    {
      const size_t len =
          FindMatchLengthWithLimit(&source[offset], &data[cur_ix_masked], limit);
      if (len >= 4) {
        size_t score = BackwardReferenceScore(len, distance);
        if (best_score < score) {
          best_score = score;
          best_len = len;
          out->len = best_len;
          out->len_code_delta = 0;
          out->distance = distance;
          out->score = best_score;
        }
      }
    }
  }
}

void BrLookupCompoundDictionaryMatch(const BrEncoderParams* params,
                                     const uint8_t* data,
                                     size_t ring_buffer_mask,
                                     const int* distance_cache, size_t cur_ix,
                                     size_t max_length,
                                     size_t max_ring_buffer_distance,
                                     size_t max_distance,
                                     HasherSearchResult* sr) {
  const PreparedDict* pd = GetPrepared(params);
  size_t base_offset = max_ring_buffer_distance + 1 + params->dict_len - 1;
  FindCompoundDictionaryMatch(pd, data, ring_buffer_mask, distance_cache,
                              cur_ix, max_length, base_offset, max_distance,
                              sr);
}

size_t BrLookupAllCompoundDictionaryMatches(const BrEncoderParams* params,
                                            const uint8_t* data,
                                            size_t ring_buffer_mask,
                                            size_t cur_ix, size_t min_length,
                                            size_t max_length,
                                            size_t max_ring_buffer_distance,
                                            size_t max_distance,
                                            void* matches_v,
                                            size_t match_limit) {
  BackwardMatch* matches = (BackwardMatch*)matches_v;
  const PreparedDict* self = GetPrepared(params);
  const size_t distance_offset =
      max_ring_buffer_distance + 1 + params->dict_len - 1;
  const uint32_t source_size = self->source_size;
  const uint32_t hash_shift = 64u - self->bucket_bits;
  const uint32_t slot_mask = (~((uint32_t)0U)) >> (32 - self->slot_bits);
  const uint64_t hash_mask = (~((uint64_t)0U)) >> (64 - self->hash_bits);
  const uint8_t* source = self->source;
  const size_t cur_ix_masked = cur_ix & ring_buffer_mask;
  size_t best_len = min_length;
  const uint64_t h = (Load64(&data[cur_ix_masked]) & hash_mask) * kHashMul64Long;
  const uint32_t key = (uint32_t)(h >> hash_shift);
  const uint32_t slot = key & slot_mask;
  const uint32_t head = self->heads[key];
  const uint32_t* chain = &self->items[self->slot_offsets[slot] + head];
  uint32_t item = (head == 0xFFFF) ? 1 : 0;
  size_t found = 0;
  while (item == 0) {
    size_t offset;
    size_t distance;
    size_t limit;
    size_t len;
    item = *chain;
    chain++;
    offset = item & 0x7FFFFFFF;
    item &= 0x80000000;
    distance = distance_offset - offset;
    limit = source_size - offset;
    limit = (limit > max_length) ? max_length : limit;
    if (distance > max_distance) continue;
    if (cur_ix_masked + best_len > ring_buffer_mask || best_len >= limit ||
        data[cur_ix_masked + best_len] != source[offset + best_len]) {
      continue;
    }
    len = FindMatchLengthWithLimit(&source[offset], &data[cur_ix_masked], limit);
    if (len > best_len) {
      best_len = len;
      InitBackwardMatch(matches++, distance, len);
      found++;
      if (found == match_limit) break;
    }
  }
  return found;
}

void BrMergeMatches(void* dst_v, void* src1_v, size_t len1, void* src2_v,
                    size_t len2) {
  BackwardMatch* dst = (BackwardMatch*)dst_v;
  BackwardMatch* src1 = (BackwardMatch*)src1_v;
  BackwardMatch* src2 = (BackwardMatch*)src2_v;
  while (len1 > 0 && len2 > 0) {
    size_t l1 = BackwardMatchLength(src1);
    size_t l2 = BackwardMatchLength(src2);
    if (l1 < l2 || ((l1 == l2) && (src1->distance < src2->distance))) {
      *dst++ = *src1++;
      len1--;
    } else {
      *dst++ = *src2++;
      len2--;
    }
  }
  while (len1-- > 0) *dst++ = *src1++;
  while (len2-- > 0) *dst++ = *src2++;
}
